//! Bounded retry policy with exponential backoff for transient model failures.
//!
//! Long-running, generation-bound model turns can trip a per-turn deadline or
//! drop mid-stream (a network reset, a stalled provider, a transient 5xx). When
//! a failure is *temporal* — reported by [`agent_runtime::Error::is_retryable`]
//! — replaying the turn recovers it: each attempt is a fresh request that gets a
//! new deadline. This module decides how many attempts to make and how long to
//! wait between them, growing the wait exponentially up to a cap. The backoff
//! schedule is deterministic (no jitter) so behavior is reproducible.

use std::time::Duration;

/// Default total attempts for one turn, including the initial try.
pub const DEFAULT_MAX_ATTEMPTS: u32 = 3;
/// Default delay before the first retry.
pub const DEFAULT_RETRY_BASE_DELAY: Duration = Duration::from_secs(2);
/// Default upper bound on any single backoff delay.
pub const DEFAULT_RETRY_MAX_DELAY: Duration = Duration::from_secs(30);

/// A bounded retry policy: how many attempts to make for one turn and how long
/// to wait between them.
///
/// `max_attempts` counts the initial attempt plus retries, so `max_attempts ==
/// 1` disables retrying.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RetryPolicy {
    /// Total attempts for one turn, including the first (`>= 1`).
    pub max_attempts: u32,
    /// Delay before the first retry; the base for exponential growth.
    pub base_delay: Duration,
    /// Upper bound on any single backoff delay.
    pub max_delay: Duration,
}

impl Default for RetryPolicy {
    fn default() -> Self {
        Self {
            max_attempts: DEFAULT_MAX_ATTEMPTS,
            base_delay: DEFAULT_RETRY_BASE_DELAY,
            max_delay: DEFAULT_RETRY_MAX_DELAY,
        }
    }
}

impl RetryPolicy {
    /// Builds a policy, clamping invalid fields to sane bounds:
    /// `max_attempts` at least 1, `base_delay` within `[1ms, max_delay]`, and
    /// `max_delay` at least `base_delay`.
    pub fn new(max_attempts: u32, base_delay: Duration, max_delay: Duration) -> Self {
        // `max_delay` is the hard ceiling (never below 1ms); `base_delay` is then
        // clamped so it can never exceed that ceiling, and is floored at 1ms so a
        // zero base delay still schedules a finite, non-zero backoff.
        let max_delay = max_delay.max(Duration::from_millis(1));
        let base_delay = base_delay.min(max_delay).max(Duration::from_millis(1));
        Self {
            max_attempts: max_attempts.max(1),
            base_delay,
            max_delay,
        }
    }

    /// The backoff delay that precedes attempt `attempt`, which is 2-based: the
    /// delay before the second (first retry) attempt is the base delay, before
    /// the third it doubles, and so on, capped at `max_delay`.
    ///
    /// Computed by repeated doubling with an early return on the cap, so it can
    /// never overflow `Duration`.
    pub fn backoff_delay(&self, attempt: u32) -> Duration {
        // `attempt == 2` is the first retry (exponent 0). Clamp defensively for
        // any smaller or absurdly large value.
        let exponent = attempt.saturating_sub(2).min(32);
        let mut delay = self.base_delay;
        for _ in 0..exponent {
            match delay.checked_mul(2) {
                Some(next) if next < self.max_delay => delay = next,
                _ => return self.max_delay,
            }
        }
        delay.min(self.max_delay)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn secs(secs: u64) -> Duration {
        Duration::from_secs(secs)
    }

    #[test]
    fn default_policy_is_triple_attempt_with_growing_backoff() {
        let policy = RetryPolicy::default();
        assert_eq!(policy.max_attempts, DEFAULT_MAX_ATTEMPTS);
        assert_eq!(policy.base_delay, DEFAULT_RETRY_BASE_DELAY);
        assert_eq!(policy.max_delay, DEFAULT_RETRY_MAX_DELAY);
    }

    #[test]
    fn backoff_grows_exponentially_then_caps() {
        let policy = RetryPolicy::new(5, secs(2), secs(30));
        assert_eq!(policy.backoff_delay(2), secs(2));
        assert_eq!(policy.backoff_delay(3), secs(4));
        assert_eq!(policy.backoff_delay(4), secs(8));
        assert_eq!(policy.backoff_delay(5), secs(16));
        assert_eq!(policy.backoff_delay(6), secs(30));
        assert_eq!(policy.backoff_delay(100), secs(30));
    }

    #[test]
    fn backoff_never_overflows_for_extreme_attempts() {
        let policy = RetryPolicy::new(2, Duration::from_nanos(1), secs(3600));
        assert!(policy.backoff_delay(10_000) <= secs(3600));
        assert!(!policy.backoff_delay(10_000).is_zero());
    }

    #[test]
    fn invalid_fields_are_clamped_to_sane_bounds() {
        let policy = RetryPolicy::new(0, Duration::ZERO, Duration::from_secs(5));
        assert_eq!(policy.max_attempts, 1);
        assert_eq!(policy.base_delay, Duration::from_millis(1));
        assert_eq!(policy.max_delay, Duration::from_secs(5));

        let policy = RetryPolicy::new(3, secs(60), secs(10));
        assert_eq!(policy.base_delay, secs(10));
        assert_eq!(policy.max_delay, secs(10));
        assert_eq!(policy.backoff_delay(3), secs(10));
    }

    #[test]
    fn single_attempt_policy_has_no_retry() {
        let policy = RetryPolicy::new(1, secs(1), secs(5));
        assert_eq!(policy.max_attempts, 1);
    }
}

//! The worker thread that runs a session loop off the UI thread.
//!
//! The model transport and sandbox executor are blocking, so the loop runs on a
//! detached thread and pushes [`Event`]s over a bounded channel. The UI owns the
//! channel receiver and renders each event. Cancellation flows from a shared
//! [`CancellationToken`], and new prompts flow from the UI over a prompt channel.

use std::sync::mpsc;
use std::thread::{self, JoinHandle};

use agent_runtime::{CancellationToken, ModelTransport};

use crate::context::ContextManager;
use crate::error::{Error, Result};
use crate::retry::RetryPolicy;
use crate::session::{
    AgentRunner, AgentSession, Event, EventSink, MAX_TURNS, Recorder, ToolExecutor,
};

/// Receives [`Event`]s from the worker; implements [`EventSink`].
struct ChannelSink(mpsc::SyncSender<Event>);

impl EventSink for ChannelSink {
    fn send(&self, event: Event) -> Result<()> {
        self.0.send(event).map_err(|_| Error::ChannelClosed)
    }
}

/// A handle to a running session, holding the cancellation token and thread.
pub struct SessionHandle {
    cancellation: CancellationToken,
    thread: Option<JoinHandle<()>>,
}

impl SessionHandle {
    /// Requests cancellation of the running turn.
    pub fn cancel(&self) {
        self.cancellation.cancel();
    }

    /// Reports whether a turn is still running.
    #[allow(dead_code)]
    pub fn is_running(&self) -> bool {
        self.thread.is_some()
    }
}

impl Drop for SessionHandle {
    fn drop(&mut self) {
        self.cancel();
        if let Some(thread) = self.thread.take() {
            let _ = thread.join();
        }
    }
}

/// Starts a session loop on a worker thread and returns a handle, the event
/// receiver owned by the UI, and the prompt sender the UI uses to submit prompts.
///
/// `context` bounds the model's context across the whole session, and an
/// optional `recorder` captures the durable record (journal + transcript,
/// including reasoning) for later inspection.
pub fn start<M, E>(
    mut session: AgentSession,
    transport: M,
    executor: E,
    mut context: ContextManager,
    mut recorder: Option<Box<dyn Recorder>>,
    retry: RetryPolicy,
) -> (SessionHandle, mpsc::Receiver<Event>, mpsc::Sender<String>)
where
    M: ModelTransport + Send + 'static,
    E: ToolExecutor + Send + 'static,
{
    let (prompt_tx, prompt_rx) = mpsc::channel::<String>();
    let (tx, rx) = mpsc::sync_channel(128);
    let cancellation = CancellationToken::new();
    let handle_cancellation = cancellation.clone();
    let thread = thread::spawn(move || {
        let sink = ChannelSink(tx);
        // The worker stays alive across turns; it exits only when every prompt
        // sender is dropped. `AgentRunner::run` records each turn's session
        // boundary in the durable recorder, so the worker does not manage the
        // record lifecycle itself. Cancellation re-arms the token after each
        // turn so a cancelled turn does not end the session.
        while let Some(text) = wait_for_prompt(&prompt_rx) {
            session.push_user(text);
            let runner = AgentRunner::with_retry(MAX_TURNS, retry);
            // Borrow the recorder only for this run; the borrow ends before the
            // next iteration, and each run starts and finishes its own record.
            let _ = runner
                .run(
                    &mut session,
                    &transport,
                    &executor,
                    &sink,
                    &cancellation,
                    &mut context,
                    borrow_recorder(&mut recorder),
                )
                .unwrap_or_else(|_| crate::session::RunSummary::default());
            cancellation.reset();
        }
    });
    (
        SessionHandle {
            cancellation: handle_cancellation,
            thread: Some(thread),
        },
        rx,
        prompt_tx,
    )
}

/// Blocks until the next prompt arrives or every prompt sender is dropped.
/// Returns `None` when the channel closes, which ends the worker.
fn wait_for_prompt(rx: &mpsc::Receiver<String>) -> Option<String> {
    rx.recv().ok()
}

/// Reborrow the recorder as `Option<&mut dyn Recorder>` for a single call.
///
/// The split borrow reborrows through the `Box`, so the mutable borrow ends
/// with the call instead of being extended across the recorder's lifetime (as a
/// direct `recorder.as_deref_mut()` borrow would be, because the value owns its
/// drop). The recorder is reused across turns, so each call needs a fresh one.
fn borrow_recorder(recorder: &mut Option<Box<dyn Recorder>>) -> Option<&mut dyn Recorder> {
    match recorder {
        Some(boxed) => Some(&mut **boxed),
        None => None,
    }
}

/// Builds the default system prompt for the agent, describing its sandbox scope.
pub fn system_prompt(write_root: &str) -> String {
    format!(
        "You are a coding agent running inside a sandbox. The working directory is mounted at {write_root} \
         and is the only place you may write. You can read files under {write_root} and the read-only system \
         layout. Prefer small, reversible steps. When editing files, write complete files. State what you did."
    )
}

//! The transport-agnostic agent session and multi-turn loop.
//!
//! [`AgentSession`] owns the ordered conversation and builds turns.
//! [`AgentRunner::run`] drives the loop against any [`ModelTransport`], executes
//! the tool intents via a [`ToolExecutor`], and forwards progress through an
//! [`EventSink`]. Nothing here performs blocking subprocess I/O directly; the
//! executor is injected so the loop is unit-testable with fakes.

use std::time::{Duration, Instant};

use agent_runtime::{
    CancellationToken, ModelMessage, ModelRequest, ModelStreamEvent, ModelTransport, ModelTurn,
    ModelUsage, ReasoningEffort, ToolChoice, ToolDefinition, ToolIntent,
};

use crate::config::Model;
use crate::context::ContextManager;
use crate::error::Result;
use crate::retry::RetryPolicy;
use crate::sandbox::ToolOutcome;

/// The maximum number of model turns in one session before the loop stops.
pub const MAX_TURNS: u32 = 50;
/// The maximum bytes of a tool result folded back to the model.
pub const MAX_TOOL_RESULT_BYTES: usize = 64 * 1024;

/// Minimum gap between live progress updates emitted while a turn streams, so
/// the stats bar tracks progress without flooding the sink on every token.
const LIVE_PROGRESS_INTERVAL: Duration = Duration::from_millis(250);

/// Read-only, turn-scoped state the streaming loop uses to emit live progress.
///
/// The provider's token usage is not known until the turn ends, so the running
/// output estimate is derived from the characters streamed so far; the context
/// figures come from the session's live context, which does not change mid-turn.
struct LiveProgress<'a> {
    session: &'a AgentSession,
    context: &'a ContextManager,
    tool_defs: usize,
    started_at: Instant,
    cumulative_total: u64,
}

/// Emits a single live progress update while a turn streams, so the stats bar
/// shows working speed, context, and elapsed time as the model generates rather
/// than only after the turn completes. Best-effort: a closed sink only means the
/// UI is gone. The running output is estimated from streamed characters because
/// the provider reports usage only when the turn ends.
fn emit_live_progress<S: EventSink>(
    sink: &S,
    progress: &LiveProgress,
    output_chars: u64,
    at: Instant,
) -> Result<()> {
    let output_tokens = output_chars.div_ceil(4);
    let elapsed = at
        .saturating_duration_since(progress.started_at)
        .as_secs_f64()
        .max(1e-9);
    let total_tokens = progress.cumulative_total.saturating_add(output_tokens);
    sink.send(Event::Progress {
        input_tokens: progress.cumulative_total,
        output_tokens,
        context_tokens: progress.session.estimate_context_tokens(progress.tool_defs),
        context_limit: progress.context.limit_tokens(),
        context_utilization: progress
            .session
            .utilization(progress.context, progress.tool_defs),
        compaction_progress: progress
            .session
            .compaction_progress(progress.context, progress.tool_defs),
        tokens_per_sec: total_tokens as f64 / elapsed,
        total_tokens,
        elapsed_secs: elapsed,
    })
}

/// A progress event emitted while a session runs.
#[derive(Debug, Clone)]
pub enum Event {
    /// A model turn began.
    TurnStart { model: String },
    /// A fragment of model reasoning text.
    Reasoning(String),
    /// A fragment of model answer text.
    Text(String),
    /// A tool call was proposed by the model, with a short human description of
    /// what it applies to (the file, directory, or command).
    ToolCall { description: String, name: String },
    /// A tool call finished; `failed` marks a non-zero or non-exiting result.
    ToolResult {
        description: String,
        name: String,
        failed: bool,
    },
    /// The session produced a final answer.
    Finished { message: String },
    /// The session failed before producing an answer.
    Failed(String),
    /// A non-terminal notice (for example, a compaction that trimmed the model
    /// context). Rendered as a muted line rather than an error.
    Note(String),
    /// Periodic context/token accounting, emitted after each turn, feeding the
    /// live speed stat, the context bargraph, and the compaction progress bar.
    Progress {
        /// Cumulative input tokens so far.
        input_tokens: u64,
        /// Cumulative output tokens so far.
        output_tokens: u64,
        /// Tokens the model currently holds in context.
        context_tokens: usize,
        /// The model context limit, in tokens.
        context_limit: usize,
        /// Context utilization against the limit (`0.0..=1.0+`).
        context_utilization: f64,
        /// How close compaction is to the hard limit (`0.0..=1.0`).
        compaction_progress: f64,
        /// Session-wide tokens per second.
        tokens_per_sec: f64,
        /// Cumulative provider tokens observed across the session.
        total_tokens: u64,
        /// Wall-clock seconds since the run started.
        elapsed_secs: f64,
    },
}

/// The sink that receives [`Event`]s, typically a channel to the UI.
pub trait EventSink: Send {
    /// Forwards one event; an error (e.g. a closed channel) stops the loop.
    fn send(&self, event: Event) -> Result<()>;
}

/// The transport-agnostic conversation state.
pub struct AgentSession {
    model: Model,
    thinking_effort: ReasoningEffort,
    system_prompt: String,
    messages: Vec<ModelMessage>,
    tool_defs: Vec<ToolDefinition>,
    answer: Option<String>,
}

impl AgentSession {
    /// Creates an empty session for one model.
    pub fn new(
        model: Model,
        thinking_effort: ReasoningEffort,
        tool_defs: Vec<ToolDefinition>,
        system_prompt: String,
    ) -> Self {
        AgentSession {
            model,
            thinking_effort,
            system_prompt,
            messages: Vec::new(),
            tool_defs,
            answer: None,
        }
    }

    /// Appends a user message. The session then has pending work.
    pub fn push_user(&mut self, text: impl Into<String>) {
        self.messages.push(ModelMessage::User(text.into()));
    }

    /// The model selector id for this session.
    pub fn model_selector(&self) -> &str {
        &self.model.id
    }

    /// The tool definitions offered to the model, whose count is used to size
    /// the model context. Exposed so context accounting can include them.
    pub fn tool_definitions(&self) -> &[ToolDefinition] {
        &self.tool_defs
    }

    /// The next turn request, or `None` when there is no pending work.
    pub fn next_request(&self) -> Option<ModelRequest> {
        if self.messages.is_empty() {
            return None;
        }
        // The system prompt is host-owned instructions, so it leads the
        // conversation as a `System` message ahead of the user history.
        let mut messages = Vec::with_capacity(self.messages.len() + 1);
        if !self.system_prompt.is_empty() {
            messages.push(ModelMessage::System(self.system_prompt.clone()));
        }
        messages.extend(self.messages.iter().cloned());
        Some(ModelRequest {
            model: self.model.model.clone(),
            messages,
            tools: self.tool_defs.clone(),
            tool_choice: ToolChoice::Auto,
            reasoning_effort: Some(self.thinking_effort),
            output_schema: None,
        })
    }

    /// Folds an assistant turn into the conversation and returns the tool
    /// intents it proposed, which the caller must execute.
    pub fn apply_assistant(&mut self, turn: ModelTurn) -> Vec<ToolIntent> {
        let tool_intents = turn.tool_intents.clone();
        self.messages.push(ModelMessage::Assistant {
            text: turn.text.clone(),
            tool_intents: turn.tool_intents,
        });
        if tool_intents.is_empty() {
            self.answer = Some(turn.text);
        }
        tool_intents
    }

    /// Records one tool result, redacted and bounded, as a model message.
    pub fn record_tool_result(&mut self, call_id: &str, name: &str, outcome: &ToolOutcome) {
        let mut body = outcome.output_text(MAX_TOOL_RESULT_BYTES);
        let stderr = outcome.error_text(MAX_TOOL_RESULT_BYTES);
        if !stderr.is_empty() {
            if !body.is_empty() {
                body.push('\n');
            }
            body.push_str(&format!("[stderr] {stderr}"));
        }
        if outcome.timed_out {
            body.push_str("\n[sandbox: wall-clock timeout]");
        }
        if outcome.output_limit_exceeded {
            body.push_str(&format!(
                "\n[sandbox: output limited to {} bytes]",
                MAX_TOOL_RESULT_BYTES
            ));
        }
        self.messages.push(ModelMessage::ToolResult {
            call_id: call_id.to_owned(),
            name: name.to_owned(),
            content: body,
        });
    }

    /// The token size of the conversation that would next be sent to the model,
    /// plus the always-present tool definitions. Used to track context usage.
    pub fn estimate_context_tokens(&self, tool_definitions: usize) -> usize {
        crate::context::estimate_messages(&self.messages, tool_definitions)
    }

    /// Compacts the conversation when it crosses the manager's warm-up threshold,
    /// rolling the oldest completed turns into a summary. Returns the compaction
    /// metadata when anything was compacted, so the caller can log and display it.
    pub fn maybe_compact(
        &mut self,
        manager: &mut ContextManager,
        tool_definitions: usize,
    ) -> Option<crate::context::Compaction> {
        let context_tokens = self.estimate_context_tokens(tool_definitions);
        if !manager.should_compact(context_tokens) {
            return None;
        }
        let (condensed, compaction) = manager.compact(&self.messages, tool_definitions);
        self.messages = condensed;
        Some(compaction)
    }

    /// The current context utilization fraction against the hard limit.
    pub fn utilization(&self, manager: &ContextManager, tool_definitions: usize) -> f64 {
        let context_tokens = self.estimate_context_tokens(tool_definitions);
        manager.utilization(context_tokens)
    }

    /// How close compaction is to the hard limit, as a progress fraction.
    pub fn compaction_progress(&self, manager: &ContextManager, tool_definitions: usize) -> f64 {
        let context_tokens = self.estimate_context_tokens(tool_definitions);
        manager.compaction_progress(context_tokens)
    }
}

/// Executes a tool intent and returns its sandbox outcome. Injected into the
/// loop so the loop itself needs no process or filesystem access. The executor
/// owns the working directory and the sandbox configuration.
pub trait ToolExecutor: Send {
    /// Renders and executes one tool intent inside the sandbox.
    fn execute(&self, intent: &ToolIntent, cancellation: &CancellationToken)
    -> Result<ToolOutcome>;
}

/// A durable, pluggable sink for the session record. The production
/// implementation ([`crate::session_log::SessionLog`]) writes a structured
/// journal and a readable transcript; tests can record in memory. Recording the
/// full reasoning trace here is what keeps thinking inspectable even after
/// compaction removes it from the model context.
pub trait Recorder: Send {
    /// Writes the session-start event. Called once, before the first turn.
    fn session_start(&mut self);
    /// Begins one turn, capturing its reasoning trace. Returns the turn index
    /// used by later tool records.
    fn turn_start(&mut self, turn: &ModelTurn) -> usize;
    /// Completes one turn, folding in provider token usage.
    fn turn_finish(&mut self, turn: usize, usage: &Option<ModelUsage>, finish_reason: &str);
    /// Records an approved tool call and its sandbox outcome.
    fn tool_result(
        &mut self,
        turn: usize,
        call_id: &str,
        tool: &str,
        args: &serde_json::Value,
        outcome: &ToolOutcome,
    );
    /// Writes the terminal session-finish event with session totals.
    fn session_finish(&mut self, success: bool);
}

/// The outcome of running a session loop.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct RunSummary {
    /// The final answer text, when the loop produced one.
    pub answer: Option<String>,
    /// The number of model turns performed.
    pub turns: u32,
    /// The number of tool calls executed.
    pub tools_executed: u32,
    /// Whether the user cancelled the loop.
    pub cancelled: bool,
    /// Whether the loop stopped after too many turns.
    pub exhausted: bool,
}

/// Maps a `FinishReason` to a short, stable string for the session record.
fn finish_reason_str(reason: &agent_runtime::FinishReason) -> &str {
    match reason {
        agent_runtime::FinishReason::Stop => "stop",
        agent_runtime::FinishReason::Length => "length",
        agent_runtime::FinishReason::ToolCalls => "tool_calls",
        agent_runtime::FinishReason::ContentFilter => "content_filter",
        agent_runtime::FinishReason::Other(s) => s.as_str(),
    }
}

/// The multi-turn loop driver.
pub struct AgentRunner {
    pub max_turns: u32,
    /// How to retry a turn that ends in a transient, recoverable failure.
    pub retry: RetryPolicy,
}

impl Default for AgentRunner {
    fn default() -> Self {
        AgentRunner {
            max_turns: MAX_TURNS,
            retry: RetryPolicy::default(),
        }
    }
}

impl AgentRunner {
    /// Creates a loop driver with an explicit retry policy.
    pub fn with_retry(max_turns: u32, retry: RetryPolicy) -> Self {
        AgentRunner { max_turns, retry }
    }
}

impl AgentRunner {
    /// Runs the loop to completion, streaming [`Event`]s through `sink`.
    ///
    /// Each parameter is a distinct collaborator the loop needs: `session` (the
    /// conversation), `transport` (the model), `executor` (sandbox tools),
    /// `sink` (events to the UI), `cancellation` (cooperative interrupt),
    /// `context` (rolling compaction bound), and an optional `recorder` that
    /// captures the durable record (reasoning included) for later inspection.
    /// Compaction only ever trims the model context; the recorder is the
    /// durable source of truth.
    #[allow(clippy::too_many_arguments)]
    pub fn run<M, E, S>(
        &self,
        session: &mut AgentSession,
        transport: &M,
        executor: &E,
        sink: &S,
        cancellation: &CancellationToken,
        context: &mut ContextManager,
        mut recorder: Option<&mut dyn Recorder>,
    ) -> Result<RunSummary>
    where
        M: ModelTransport,
        E: ToolExecutor,
        S: EventSink,
    {
        let tool_definitions = session.tool_definitions().len();
        let mut summary = RunSummary::default();
        let mut turn = 0u32;
        let started_at = Instant::now();
        let mut cumulative_tokens: u64 = 0;
        let mut cumulative_input: u64 = 0;
        let mut cumulative_output: u64 = 0;

        // Record the durable session boundary before any turn, so the record
        // has a clean start (and a matching finish) even for an empty run.
        if let Some(recorder) = recorder.as_mut() {
            recorder.session_start();
        }

        while turn < self.max_turns {
            let Some(request) = session.next_request() else {
                break;
            };
            turn += 1;

            sink.send(Event::TurnStart {
                model: session.model_selector().to_owned(),
            })?;

            // Stream the turn, forwarding text/reasoning/tool intents to the UI
            // and retrying transient failures with backoff (see `drive_turn`).
            // A turn that cannot be recovered after exhausting the policy is
            // surfaced as an `Event::Failed` and stops the session, matching the
            // pre-retry contract rather than aborting the run with an error.
            let turn_value = match self.drive_turn(
                &request,
                transport,
                sink,
                cancellation,
                &LiveProgress {
                    session,
                    context,
                    tool_defs: tool_definitions,
                    started_at,
                    cumulative_total: cumulative_input + cumulative_output,
                },
            ) {
                Ok(turn) => turn,
                Err(error) => {
                    sink.send(Event::Failed(error.to_string()))?;
                    summary.cancelled = cancellation.is_cancelled();
                    // Account for the turn that was attempted before stopping, so
                    // the failure summary mirrors the normal completion path
                    // (which sets `turns` and `answer` after the loop).
                    summary.turns = turn;
                    summary.answer = session.answer.clone();
                    return Ok(summary);
                }
            };

            // Capture the full record first: reasoning + finish + usage. This is
            // the durable copy that compaction and the UI may later drop.
            let turn_index = recorder.as_mut().map(|rec| rec.turn_start(&turn_value));
            let finish_reason = finish_reason_str(&turn_value.finish_reason);
            if let Some(recorder) = recorder.as_mut() {
                recorder.turn_finish(turn_index.unwrap_or(0), &turn_value.usage, finish_reason);
            }
            if let Some(usage) = &turn_value.usage {
                cumulative_tokens += usage.total_tokens;
                cumulative_input += usage.input_tokens;
                cumulative_output += usage.output_tokens;
            }

            // No tools proposed: this assistant text is the final answer.
            let tool_intents = session.apply_assistant(turn_value);
            let terminal = tool_intents.is_empty();

            if !terminal {
                for intent in tool_intents {
                    if cancellation.is_cancelled() {
                        summary.cancelled = true;
                        return Ok(summary);
                    }
                    match executor.execute(&intent, cancellation) {
                        Ok(outcome) => {
                            summary.tools_executed += 1;
                            session.record_tool_result(&intent.id, &intent.name, &outcome);
                            if let Some(recorder) = recorder.as_mut() {
                                recorder.tool_result(
                                    turn_index.unwrap_or(0),
                                    &intent.id,
                                    &intent.name,
                                    &intent.arguments,
                                    &outcome,
                                );
                            }
                            let _ = sink.send(Event::ToolResult {
                                description: crate::tools::describe_tool_call(&intent),
                                name: intent.name.clone(),
                                failed: outcome.failed(),
                            });
                        }
                        Err(error) => {
                            // A rejected or failed tool is reported, not fatal.
                            if let Some(recorder) = recorder.as_mut() {
                                recorder.tool_result(
                                    turn_index.unwrap_or(0),
                                    &intent.id,
                                    &intent.name,
                                    &intent.arguments,
                                    &crate::sandbox::ToolOutcome::rejected(),
                                );
                            }
                            let _ = sink.send(Event::ToolResult {
                                description: crate::tools::describe_tool_call(&intent),
                                name: intent.name.clone(),
                                failed: true,
                            });
                            let _ = sink.send(Event::Failed(error.describe()));
                        }
                    }

                    // Compact the model context now that this turn is fully
                    // recorded, so the next request stays within the model's
                    // window. The record is untouched.
                    if let Some(compaction) = session.maybe_compact(context, tool_definitions)
                        && compaction.compacted_turns > 0
                    {
                        let _ = sink.send(Event::Note(format!(
                        "context compacted: {} earlier turn(s) rolled into a summary (kept in the session log)",
                        compaction.compacted_turns
                    )));
                    }
                }
            }

            // Report accounting after every turn — including the final one,
            // whose report doubles as the session's last — so the live stats
            // bar (speed, context utilization, compaction progress, and the
            // compaction ETA) tracks the session while it runs, not only when
            // it ends.
            self.emit_progress(
                sink,
                session,
                context,
                cumulative_input,
                cumulative_output,
                cumulative_tokens,
                started_at,
            )?;
            if terminal {
                break;
            }
        }

        if turn >= self.max_turns {
            summary.exhausted = true;
        }
        summary.turns = turn;
        summary.answer = session.answer.clone();
        if let Some(answer) = &summary.answer {
            let _ = sink.send(Event::Finished {
                message: answer.clone(),
            });
        }
        // Close the durable session record. A run that was cancelled or
        // exhausted after too many turns is recorded as unsuccessful; a normal
        // completion (with or without a final answer) is recorded as success.
        let success = !summary.cancelled && !summary.exhausted;
        if let Some(recorder) = recorder.as_mut() {
            recorder.session_finish(success);
        }
        Ok(summary)
    }

    /// Streams one turn, retrying transient failures with bounded backoff.
    ///
    /// The loop reuses the same [`ModelRequest`] (rebuildable from the session,
    /// which excludes any partial output of a failed attempt) across attempts so
    /// a retry replays the turn from a clean state. Each attempt is a fresh
    /// transport call, so it also gets a fresh per-turn deadline: a turn that
    /// merely ran past its deadline once can finish on the next attempt.
    ///
    ///
    /// While a turn streams, a live progress update is emitted at a bounded rate
    /// so the stats bar tracks working speed, context, and elapsed time as the
    /// model generates, not only after the turn ends.
    ///
    /// A failure is retried only when [`agent_runtime::Error::is_retryable`]
    /// reports it as a temporal, recoverable condition (network drop, provider
    /// timeout, transient server error). Cancellation is never retried, and once
    /// the policy's attempt budget is spent the final error is returned so the
    /// caller reports it. Between attempts an [`Event::Note`] is emitted so the
    /// user sees the retry is in progress; the best-effort sink send only means
    /// the UI is gone.
    fn drive_turn<M, S>(
        &self,
        request: &ModelRequest,
        transport: &M,
        sink: &S,
        cancellation: &CancellationToken,
        progress: &LiveProgress,
    ) -> agent_runtime::Result<ModelTurn>
    where
        M: ModelTransport,
        S: EventSink,
    {
        // Each retryable attempt is granted a larger budget than the last so a
        // turn that merely ran past one deadline can finish once an attempt has
        // room for the whole generation. The budget grows linearly with the
        // attempt number and is capped at `base × max_attempts`, so a recoverable
        // timeout can never turn a single transport call into an unbounded wait;
        // the first attempt uses the transport's configured deadline unchanged.
        let base = transport.deadline();
        let mut attempt = 1u32;
        loop {
            let attempt_deadline = base
                .saturating_mul(attempt)
                .min(base.saturating_mul(self.retry.max_attempts));
            let attempt_deadline_secs = attempt_deadline.as_secs_f64();
            // Running output estimate and last live-update time for this attempt,
            // so the stats bar refreshes at a bounded rate while the model streams
            // rather than only after the turn completes.
            let mut attempt_output_chars: u64 = 0;
            let mut last_emit = Instant::now();
            // The callback must return `agent_runtime::Result`, so forwarding to
            // the sink is best-effort: a closed channel only means the UI is gone,
            // which the loop surfaces on the next turn's own `sink.send`.
            let result = transport.stream_with_deadline(
                request,
                cancellation,
                &mut |event| {
                    match event {
                        ModelStreamEvent::TextDelta(delta) => {
                            if !delta.is_empty() {
                                attempt_output_chars += delta.chars().count() as u64;
                                let _ = sink.send(Event::Text(delta));
                            }
                        }
                        ModelStreamEvent::ReasoningDelta(delta) => {
                            if !delta.is_empty() {
                                attempt_output_chars += delta.chars().count() as u64;
                                let _ = sink.send(Event::Reasoning(delta));
                            }
                        }
                        ModelStreamEvent::ToolIntent(intent) => {
                            let description = crate::tools::describe_tool_call(&intent);
                            let _ = sink.send(Event::ToolCall {
                                description,
                                name: intent.name.clone(),
                            });
                        }
                    }
                    // Refresh the live stats bar at a bounded rate so the user
                    // sees the turn making progress while the model streams.
                    let now = Instant::now();
                    if now.saturating_duration_since(last_emit) >= LIVE_PROGRESS_INTERVAL {
                        last_emit = now;
                        let _ = emit_live_progress(sink, progress, attempt_output_chars, now);
                    }
                    Ok(())
                },
                attempt_deadline,
            );

            match result {
                Ok(turn) => return Ok(turn),
                // Retry only temporal, recoverable failures, and only while the
                // attempt budget remains and the turn was not cancelled.
                Err(error) if error.is_retryable() => {
                    if attempt >= self.retry.max_attempts || cancellation.is_cancelled() {
                        return Err(error);
                    }
                    let next = attempt + 1;
                    let delay = self.retry.backoff_delay(next);
                    let delay_secs = delay.as_secs_f64();
                    // Show the turn is recovering and that a longer budget is
                    // being granted, not just another identical try.
                    let _ = sink.send(Event::Note(format!(
                        "model request failed ({error}); retrying {next}/{max} in {delay_secs:.1}s with a {attempt_deadline_secs:.0}s budget",
                        max = self.retry.max_attempts,
                    )));
                    attempt = next;
                    std::thread::sleep(delay);
                }
                Err(error) => return Err(error),
            }
        }
    }

    /// Emits a single accounting event so the UI can update the speed stat, the
    /// context bargraph, and the compaction progress bar. Non-fatal: a dropped
    /// sink only means the UI is gone.
    #[allow(clippy::too_many_arguments)]
    fn emit_progress<S: EventSink>(
        &self,
        sink: &S,
        session: &AgentSession,
        context: &ContextManager,
        input_tokens: u64,
        output_tokens: u64,
        total_tokens: u64,
        started_at: Instant,
    ) -> Result<()> {
        let context_tokens = session.estimate_context_tokens(session.tool_definitions().len());
        let elapsed = started_at.elapsed().as_secs_f64().max(1e-9);
        let tokens_per_sec = total_tokens as f64 / elapsed;
        sink.send(Event::Progress {
            input_tokens,
            output_tokens,
            context_tokens,
            context_limit: context.limit_tokens(),
            context_utilization: session.utilization(context, session.tool_definitions().len()),
            compaction_progress: session
                .compaction_progress(context, session.tool_definitions().len()),
            tokens_per_sec,
            total_tokens,
            elapsed_secs: elapsed,
        })
    }
}

//! Model-facing tools and their mapping to sandbox-executed commands.
//!
//! Tools never execute directly. Each [`ToolRegistry::render`] call produces an
//! argv (with an absolute canonical program) that the sandbox executes, plus an
//! optional staged write that lets the agent create files larger than the
//! sandbox argv byte limit without leaving the write root.

use std::path::PathBuf;

use agent_runtime::{ToolDefinition, ToolIntent};
use serde_json::Value;

// Re-export the policy type so consumers can refer to it as `agent_runner::tools::ToolPolicy`.
pub use crate::config::ToolPolicy;

/// The staging directory in the sandbox namespace, where a leading `/` is the
/// sandbox root (the mounted write root). Kept hidden so it does not collide
/// with user files and stays inside the writable scope.
const STAGING_DIR: &str = "/.agent-writes";
/// The staging directory on the host: the sandbox form [`STAGING_DIR`] with the
/// leading slash removed, so it joins under the working directory instead of the
/// filesystem root. `PathBuf::join` treats an absolute path as a full
/// replacement, so the host path must stay relative.
const HOST_STAGING_DIR: &str = ".agent-writes";
/// The number of leading characters kept in a tool summary.
const MAX_SUMMARY_BYTES: usize = 120;
/// The number of leading characters kept in a path summary.
const MAX_PATH_SUMMARY_CHARS: usize = 60;

/// Per-call execution context shared by rendering and execution.
#[derive(Debug, Clone)]
pub struct ExecContext {
    /// The host working directory, source of the sandbox write root.
    pub workdir: PathBuf,
    /// A unique identifier for the current tool call.
    pub call_id: String,
}

impl ExecContext {
    /// Builds an execution context for one tool call.
    pub fn new(workdir: impl Into<PathBuf>, call_id: impl Into<String>) -> Self {
        ExecContext {
            workdir: workdir.into(),
            call_id: call_id.into(),
        }
    }
}

/// A staged write: content is written to `host_path` on the host before the
/// rendered argv runs, and the argv then moves `sandbox_path` into place.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StagedWrite {
    /// The host path content must be written to before execution.
    pub host_path: PathBuf,
    /// The sandbox path the staged file appears at.
    pub sandbox_path: String,
    /// The final target path inside the sandbox.
    pub target: String,
}

/// The result of rendering a tool call.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RenderedTool {
    /// The argv to execute inside the sandbox; `argv[0]` is absolute.
    pub argv: Vec<String>,
    /// A short human description shown in the UI and logs.
    pub summary: String,
    /// Present only for staged writes (`write_file`).
    pub staged_write: Option<StagedWrite>,
}

/// Language tool profiles known to the registry.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ToolProfile {
    /// No language assumptions; generic Linux tools only.
    Generic,
    /// The Rust toolchain (cargo, rustc).
    Rust,
    /// The Python toolchain (python3, pip).
    Python,
}

impl ToolProfile {
    /// The profile identifier accepted in configuration and on the CLI.
    pub const fn id(self) -> &'static str {
        match self {
            ToolProfile::Generic => "generic",
            ToolProfile::Rust => "rust",
            ToolProfile::Python => "python",
        }
    }

    /// A human description of the toolchain the profile surfaces.
    pub const fn toolkit(self) -> &'static str {
        match self {
            ToolProfile::Generic => "coreutils, git, and common Linux tools",
            ToolProfile::Rust => "cargo, rustc, and the Rust standard toolchain",
            ToolProfile::Python => "python3, pip, and common Python build tools",
        }
    }

    /// Parses a profile identifier.
    pub fn from_id(id: &str) -> Option<Self> {
        match id {
            "generic" => Some(Self::Generic),
            "rust" => Some(Self::Rust),
            "python" => Some(Self::Python),
            _ => None,
        }
    }
}

/// The registry of model-facing tools and their sandbox rendering.
#[derive(Debug, Clone)]
pub struct ToolRegistry {
    bash: PathBuf,
    policy: ToolPolicy,
    profiles: Vec<ToolProfile>,
}

impl ToolRegistry {
    /// Builds a registry advertising the built-in generic Linux tooling plus
    /// the Rust/Cargo toolchain. Building and testing the project are essential
    /// agent capabilities, so the Rust toolchain is advertised by default; the
    /// sandbox enforces exactly a `System` and a `Cargo` toolchain, so these are
    /// the honest defaults. Python is also advertised by default: it runs under
    /// the generic `System` path from the read-only host layout, and `python3`
    /// is present on the host, so advertising it is honest. Language profiles
    /// can still be narrowed with [`ToolRegistry::with_profiles`].
    pub fn new(policy: ToolPolicy) -> Self {
        ToolRegistry {
            bash: PathBuf::from("/usr/bin/bash"),
            policy,
            profiles: vec![ToolProfile::Generic, ToolProfile::Python, ToolProfile::Rust],
        }
    }

    /// Overrides the resolved `bash` path (used by tests).
    pub fn with_bash(mut self, bash: impl Into<PathBuf>) -> Self {
        self.bash = bash.into();
        self
    }

    /// Adds language tool profiles to the registry.
    pub fn with_profiles(mut self, profiles: Vec<ToolProfile>) -> Self {
        if !profiles.is_empty() {
            self.profiles = profiles;
        }
        self
    }

    /// The tool authority policy backing this registry.
    pub fn policy(&self) -> &ToolPolicy {
        &self.policy
    }

    /// The enabled tool profile identifiers, sorted for determinism.
    pub fn profiles(&self) -> Vec<&'static str> {
        let mut ids: Vec<&'static str> = self.profiles.iter().map(|p| p.id()).collect();
        ids.sort_unstable();
        ids.dedup();
        ids
    }

    /// The tool definitions exposed to the model, in stable order.
    pub fn tool_definitions(&self) -> Vec<ToolDefinition> {
        let toolkit = self
            .profiles
            .iter()
            .map(|p| p.toolkit())
            .collect::<Vec<_>>()
            .join(", ");
        vec![
            ToolDefinition {
                name: "shell".to_owned(),
                description: format!(
                    "Run a shell command inside the sandbox. Use it to build, test, query, and \
                     manipulate the project. Available tooling: {toolkit}. Commands run under the \
                     working directory scope; writes outside it are refused."
                ),
                parameters: serde_json::json!({
                    "type": "object",
                    "properties": {
                        "command": {
                            "type": "string",
                            "description": "The shell command to run."
                        }
                    },
                    "required": ["command"],
                }),
            },
            ToolDefinition {
                name: "read_file".to_owned(),
                description: "Read a text file inside the sandbox and return its contents."
                    .to_owned(),
                parameters: serde_json::json!({
                    "type": "object",
                    "properties": {
                        "path": {
                            "type": "string",
                            "description": "The absolute path of the file to read."
                        }
                    },
                    "required": ["path"],
                }),
            },
            ToolDefinition {
                name: "write_file".to_owned(),
                description:
                    "Write content to a file inside the working directory (create or overwrite)."
                        .to_owned(),
                parameters: serde_json::json!({
                    "type": "object",
                    "properties": {
                        "path": {
                            "type": "string",
                            "description": "The absolute path of the file to write, under the working directory."
                        },
                        "content": {
                            "type": "string",
                            "description": "The full content to write to the file."
                        }
                    },
                    "required": ["path", "content"],
                }),
            },
            ToolDefinition {
                name: "list_dir".to_owned(),
                description: "List the entries of a directory inside the sandbox.".to_owned(),
                parameters: serde_json::json!({
                    "type": "object",
                    "properties": {
                        "path": {
                            "type": "string",
                            "description": "The absolute path of the directory to list."
                        }
                    },
                    "required": ["path"],
                }),
            },
        ]
    }

    /// Resolves the canonical `bash` path and builds a registry.
    pub fn discover(policy: ToolPolicy) -> crate::error::Result<Self> {
        let bash = crate::sandbox::resolve_executable("bash")?;
        Ok(ToolRegistry::new(policy).with_bash(bash))
    }

    /// Renders a tool intent to a sandbox argv.
    pub fn render(
        &self,
        intent: &ToolIntent,
        context: &ExecContext,
    ) -> crate::error::Result<RenderedTool> {
        match intent.name.as_str() {
            "shell" => self.render_shell(intent),
            "read_file" => self.render_read(intent),
            "write_file" => self.render_write(intent, context),
            "list_dir" => self.render_list(intent),
            other => Err(crate::error::Error::ToolRender {
                tool: other.to_owned(),
                reason: "unknown or disabled tool".to_owned(),
            }),
        }
    }

    fn render_shell(&self, intent: &ToolIntent) -> crate::error::Result<RenderedTool> {
        let command = string_arg(intent, "command")?;
        if command.trim().is_empty() {
            return Err(crate::error::Error::ToolRender {
                tool: "shell".to_owned(),
                reason: "command must not be empty".to_owned(),
            });
        }
        if !self.policy.shell_permitted(&command) {
            Err(crate::error::Error::ToolPolicy {
                tool: "shell".to_owned(),
                reason: "command matches the forbidden-command policy".to_owned(),
            })
        } else {
            Ok(RenderedTool {
                argv: vec![
                    self.bash.to_string_lossy().into_owned(),
                    "-c".to_owned(),
                    command.clone(),
                    "agent-runner".to_owned(),
                ],
                summary: describe_tool_call(intent),
                staged_write: None,
            })
        }
    }

    fn render_read(&self, intent: &ToolIntent) -> crate::error::Result<RenderedTool> {
        let path = string_arg(intent, "path")?;
        Ok(RenderedTool {
            argv: vec![
                self.bash.to_string_lossy().into_owned(),
                "-c".to_owned(),
                "exec cat -- \"$1\"".to_owned(),
                "agent-runner".to_owned(),
                path.clone(),
            ],
            summary: describe_tool_call(intent),
            staged_write: None,
        })
    }

    fn render_list(&self, intent: &ToolIntent) -> crate::error::Result<RenderedTool> {
        let path = string_arg(intent, "path")?;
        Ok(RenderedTool {
            argv: vec![
                self.bash.to_string_lossy().into_owned(),
                "-c".to_owned(),
                "exec ls -la -- \"$1\"".to_owned(),
                "agent-runner".to_owned(),
                path.clone(),
            ],
            summary: describe_tool_call(intent),
            staged_write: None,
        })
    }

    fn render_write(
        &self,
        intent: &ToolIntent,
        context: &ExecContext,
    ) -> crate::error::Result<RenderedTool> {
        let path = string_arg(intent, "path")?;
        if !under_write_root(&path, &self.policy.write_root) {
            return Err(crate::error::Error::ToolPolicy {
                tool: "write_file".to_owned(),
                reason: format!(
                    "target `{path}` is outside the write root `{}`",
                    self.policy.write_root
                ),
            });
        }
        // The content is staged inside the working directory (already mounted
        // read-write as the sandbox write root) so arbitrarily large files can
        // be written without exceeding the sandbox argv byte limit, then moved
        // into place.
        let sandbox_staging = format!("{STAGING_DIR}/{}", context.call_id);
        let host_staging = context
            .workdir
            .join(HOST_STAGING_DIR)
            .join(&context.call_id);
        Ok(RenderedTool {
            argv: vec![
                self.bash.to_string_lossy().into_owned(),
                "-c".to_owned(),
                "exec mv -f -- \"$1\" \"$2\"".to_owned(),
                "agent-runner".to_owned(),
                sandbox_staging.clone(),
                path.clone(),
            ],
            summary: describe_tool_call(intent),
            staged_write: Some(StagedWrite {
                host_path: host_staging,
                sandbox_path: sandbox_staging,
                target: path,
            }),
        })
    }
}

fn string_arg(intent: &ToolIntent, field: &str) -> crate::error::Result<String> {
    match intent.arguments.get(field) {
        Some(Value::String(text)) => Ok(text.clone()),
        Some(Value::Null) | None => Err(crate::error::Error::ToolRender {
            tool: intent.name.clone(),
            reason: format!("missing required string argument `{field}`"),
        }),
        Some(other) => Err(crate::error::Error::ToolRender {
            tool: intent.name.clone(),
            reason: format!(
                "argument `{field}` must be a string, found {}",
                value_kind(other)
            ),
        }),
    }
}

fn value_kind(value: &Value) -> &'static str {
    match value {
        Value::String(_) => "string",
        Value::Number(_) => "number",
        Value::Bool(_) => "bool",
        Value::Array(_) => "array",
        Value::Object(_) => "object",
        Value::Null => "null",
    }
}

/// Whether `path` is inside `root` on a `/`-separated sandbox path namespace.
///
/// Requires the root boundary, not a bare `starts_with`, so that a sibling such
/// as `/workspace-evil` cannot be accepted when the write root is `/workspace`.
fn under_write_root(path: &str, root: &str) -> bool {
    path == root || path.starts_with(&format!("{root}/"))
}

fn summarize_path(path: &str) -> String {
    let kept: String = path.chars().take(MAX_PATH_SUMMARY_CHARS).collect();
    if kept.chars().count() == path.chars().count() {
        kept
    } else {
        format!("…{kept}")
    }
}

fn summarize(command: &str) -> String {
    let first: String = command
        .lines()
        .next()
        .unwrap_or_default()
        .trim()
        .chars()
        .take(MAX_SUMMARY_BYTES)
        .collect();
    if first.is_empty() {
        "<shell command>".to_owned()
    } else {
        first
    }
}

/// A short, human-readable description of a tool call, shown in the UI and logs.
///
/// This is the single source for the `RenderedTool.summary` each renderer
/// produces (`read {path}`, `list {path}`, `write {path}`, or the shell command
/// summary), so the live "tool proposed" line matches the executed one. It needs
/// only the intent name and arguments, so it also works in the streaming loop
/// before the call has been rendered and executed.
pub fn describe_tool_call(intent: &ToolIntent) -> String {
    match intent.name.as_str() {
        "shell" => match string_arg(intent, "command") {
            Ok(command) => summarize(&command),
            Err(_) => "<shell command>".to_owned(),
        },
        // Path-based tools: a literal verb prefixes the target path.
        "read_file" | "list_dir" | "write_file" => match string_arg(intent, "path") {
            Ok(path) => {
                let verb = match intent.name.as_str() {
                    "read_file" => "read",
                    "list_dir" => "list",
                    _ => "write",
                };
                format!("{verb} {}", summarize_path(&path))
            }
            Err(_) => intent.name.clone(),
        },
        // Any other path-accepting tool falls back to its own name as the verb.
        other => match string_arg(intent, "path") {
            Ok(path) => format!("{other} {}", summarize_path(&path)),
            Err(_) => other.to_owned(),
        },
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Building and testing the project are essential, so the default registry
    /// must advertise the generic Linux tools, the Rust/Cargo toolchain, and
    /// the Python interpreter; otherwise an agent reasonably concludes it has
    /// no compiler and declines.
    #[test]
    fn default_registry_advertises_generic_and_rust_toolchains() {
        let registry = ToolRegistry::new(ToolPolicy::minimum());
        let advertised = registry.profiles();
        // `profiles()` sorts and dedupes, so the default set is stable order.
        assert_eq!(
            advertised,
            vec!["generic", "python", "rust"],
            "default registry must advertise generic, python, and rust, got {advertised:?}"
        );
    }

    #[test]
    fn shell_tool_description_names_the_rust_toolchain() {
        let registry = ToolRegistry::new(ToolPolicy::minimum());
        let shell = registry
            .tool_definitions()
            .into_iter()
            .find(|d| d.name == "shell")
            .expect("the shell tool is always available");
        let description = shell.description.to_string();
        assert!(
            description.to_lowercase().contains("cargo"),
            "the shell tool must advertise the Rust toolchain it can build with: {description}"
        );
    }

    #[test]
    fn explicit_profile_replaces_the_default_set() {
        let registry =
            ToolRegistry::new(ToolPolicy::minimum()).with_profiles(vec![ToolProfile::Python]);
        assert_eq!(registry.profiles(), vec!["python"]);
    }
}

//! Configuration model, loading, and validation.

use std::path::{Path, PathBuf};
use std::str::FromStr;

use serde::{Deserialize, Serialize};

use crate::error::{Error, Result, io_error};

/// Maximum encoded size of a configuration file.
pub const MAX_CONFIG_BYTES: u64 = 64 * 1024;
/// The only accepted configuration schema version.
pub const SCHEMA_VERSION: u32 = 1;
/// Minimum per-turn model deadline in seconds.
const MIN_DEADLINE_SECS: u64 = 1;
/// Maximum per-turn model deadline in seconds.
const MAX_DEADLINE_SECS: u64 = 600;

/// The local model provider a model talks to.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum ModelProvider {
    /// llama-server's OpenAI-compatible HTTP protocol.
    LlamaServer,
    /// Ollama's native HTTP protocol.
    Ollama,
}

impl ModelProvider {
    /// Maps the configuration provider to the agent-runtime transport provider.
    pub const fn to_agent_provider(self) -> agent_runtime::LocalModelProvider {
        match self {
            ModelProvider::LlamaServer => agent_runtime::LocalModelProvider::LlamaServer,
            ModelProvider::Ollama => agent_runtime::LocalModelProvider::Ollama,
        }
    }

    /// The base URL the provider listens on when no override is configured.
    pub const fn default_endpoint(self) -> &'static str {
        match self {
            ModelProvider::LlamaServer => "http://127.0.0.1:9931",
            ModelProvider::Ollama => "http://127.0.0.1:11434",
        }
    }

    /// Parses the kebab-case provider spelling used in configuration files.
    pub fn parse(value: &str) -> Option<Self> {
        match value.trim().to_ascii_lowercase().as_str() {
            "llama-server" => Some(Self::LlamaServer),
            "ollama" => Some(Self::Ollama),
            _ => None,
        }
    }
}

impl FromStr for ModelProvider {
    type Err = String;

    fn from_str(value: &str) -> std::result::Result<Self, Self::Err> {
        Self::parse(value)
            .ok_or_else(|| format!("invalid provider `{value}`; expected llama-server or ollama"))
    }
}

/// One selectable model.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Model {
    /// The user-facing selector shown and accepted in the UI.
    pub id: String,
    /// The provider the model talks to.
    pub provider: ModelProvider,
    /// The provider base URL. Defaults to the provider's standard endpoint.
    #[serde(default)]
    pub base_url: String,
    /// The provider-facing model selector.
    pub model: String,
    /// The per-turn deadline in seconds.
    #[serde(default = "default_deadline")]
    pub deadline_secs: u64,
    /// Total attempts (the initial try plus retries) for one turn before giving
    /// up on a transient, recoverable failure.
    #[serde(default = "default_max_attempts")]
    pub max_attempts: u32,
    /// Base backoff delay, in seconds, before the first retry.
    #[serde(default = "default_retry_base_delay_secs")]
    pub retry_base_delay_secs: u64,
    /// Upper bound, in seconds, on any single retry backoff delay.
    #[serde(default = "default_retry_max_delay_secs")]
    pub retry_max_delay_secs: u64,
    /// Inter-token cadence watchdog timeout, in seconds. If the provider sends
    /// no token for longer than this gap after the first token, the turn is
    /// treated as stalled and retried, so a generous per-turn deadline can never
    /// turn a hung provider into a silent multi-minute hang. `0` disables the
    /// watchdog. Defaults to 30s, comfortably above the ~1s gap of a healthy
    /// stream but well below a genuine stall.
    #[serde(default = "default_cadence_timeout_secs")]
    pub cadence_timeout_secs: u64,
}

fn default_deadline() -> u64 {
    // A single long-context turn (large prefill plus thousands of generated
    // tokens) can take over a couple of minutes, so the default per-turn budget
    // comfortably covers one attempt. A stalled provider is still caught quickly
    // by the slot/TTFT/cadence watchdogs, and retries add further headroom.
    300
}

fn default_max_attempts() -> u32 {
    crate::retry::DEFAULT_MAX_ATTEMPTS
}

fn default_retry_base_delay_secs() -> u64 {
    2
}

fn default_retry_max_delay_secs() -> u64 {
    30
}

fn default_cadence_timeout_secs() -> u64 {
    30
}

/// Paths to the independent sandbox enforcement boundary.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct SandboxPaths {
    /// Path to the `kvist-sandbox-runner` executable.
    pub runner: PathBuf,
    /// Path to the Bubblewrap backend executable.
    pub backend: PathBuf,
}

impl Default for SandboxPaths {
    fn default() -> Self {
        SandboxPaths {
            runner: SandboxPaths::default_runner(),
            backend: SandboxPaths::default_backend(),
        }
    }
}

impl SandboxPaths {
    /// The default sandbox runner path when not configured.
    pub fn default_runner() -> PathBuf {
        PathBuf::from("/usr/local/bin/kvist-sandbox-runner")
    }

    /// The default Bubblewrap backend path when not configured.
    pub fn default_backend() -> PathBuf {
        PathBuf::from("/usr/bin/bwrap")
    }
}

/// The default sandbox write root: everything the agent writes stays under it.
pub const DEFAULT_WRITE_ROOT: &str = "/workspace";

/// The tool authority policy: a safe-by-default shell denylist plus the sandbox
/// write root. User configuration may only widen the denylist, never remove the
/// built-in minimum.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ToolPolicy {
    /// Shell command strings containing any of these substrings are forbidden.
    pub shell_deny_substrings: Vec<String>,
    /// Shell command strings starting with any of these prefixes are forbidden.
    pub shell_deny_prefixes: Vec<String>,
    /// The sandbox write root under which all writes are confined.
    pub write_root: String,
}

impl ToolPolicy {
    /// The safe minimum denylist applied to every configuration.
    pub fn minimum() -> Self {
        ToolPolicy {
            shell_deny_substrings: vec![
                "rm -rf".to_owned(),
                "rm -fr".to_owned(),
                "mkfs".to_owned(),
                "dd if=".to_owned(),
                "dd bs=".to_owned(),
                "> /dev/".to_owned(),
                ":() {".to_owned(),
                "exec 9<>".to_owned(),
                "reboot".to_owned(),
                "shutdown".to_owned(),
            ],
            shell_deny_prefixes: vec!["mknod ".to_owned()],
            write_root: DEFAULT_WRITE_ROOT.to_owned(),
        }
    }

    /// Parses the `[tool_policy]` table on top of the built-in minimum.
    fn from_policy_table(raw: &RawToolPolicy) -> Result<Self> {
        let mut policy = Self::minimum();
        policy
            .shell_deny_substrings
            .extend(raw.shell_deny_substrings.iter().cloned());
        policy
            .shell_deny_prefixes
            .extend(raw.shell_deny_prefixes.iter().cloned());
        if let Some(write_root) = &raw.write_root {
            if write_root.is_empty() {
                return Err(Error::Config {
                    path: None,
                    reason: "tool_policy.write_root must not be empty".to_owned(),
                });
            }
            policy.write_root = write_root.clone();
        }
        Ok(policy)
    }

    /// A stable identity derived from the enforced policy, bound into every
    /// sandbox request so the request can be traced back to the policy it ran
    /// under.
    pub fn identity(&self) -> String {
        use sha2::{Digest, Sha256};
        let mut entries = Vec::new();
        entries.push(("write_root".to_owned(), self.write_root.clone()));
        for substring in &self.shell_deny_substrings {
            entries.push(("deny-substring".to_owned(), substring.clone()));
        }
        for prefix in &self.shell_deny_prefixes {
            entries.push(("deny-prefix".to_owned(), prefix.clone()));
        }
        entries.sort();
        let mut bytes = Vec::new();
        for (key, value) in entries {
            bytes.extend_from_slice(key.as_bytes());
            bytes.push(0u8);
            bytes.extend_from_slice(value.as_bytes());
            bytes.push(0u8);
        }
        format!("sha256:{}", hex::encode(Sha256::digest(bytes)))
    }

    /// Reports whether a shell command string is permitted by this policy.
    pub fn shell_permitted(&self, command: &str) -> bool {
        if self
            .shell_deny_prefixes
            .iter()
            .any(|prefix| command.trim_start().starts_with(prefix.as_str()))
        {
            return false;
        }
        !self
            .shell_deny_substrings
            .iter()
            .any(|substring| command.contains(substring.as_str()))
    }
}

impl Default for ToolPolicy {
    fn default() -> Self {
        Self::minimum()
    }
}

/// The validated, in-memory configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Config {
    /// The configuration schema version.
    pub schema_version: u32,
    /// The working directory the agent operates in.
    pub working_directory: PathBuf,
    /// The default model selector.
    pub default_model: String,
    /// The default thinking effort.
    pub default_thinking_effort: agent_runtime::ReasoningEffort,
    /// The selectable models.
    pub models: Vec<Model>,
    /// The tool authority policy.
    pub tool_policy: crate::tools::ToolPolicy,
    /// The sandbox boundary paths.
    pub sandbox: SandboxPaths,
}

/// The intermediate TOML shape; validated into [`Config`] by [`Config::validate`].
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct RawConfig {
    schema_version: u32,
    #[serde(default)]
    working_directory: Option<String>,
    default_model: String,
    #[serde(default)]
    default_thinking_effort: Option<String>,
    #[serde(default)]
    models: Vec<RawModel>,
    #[serde(default)]
    sandbox: RawSandbox,
    #[serde(default)]
    tool_policy: RawToolPolicy,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct RawModel {
    id: String,
    provider: ModelProvider,
    #[serde(default)]
    base_url: String,
    model: String,
    #[serde(default = "default_deadline")]
    deadline_secs: u64,
    #[serde(default = "default_max_attempts")]
    max_attempts: u32,
    #[serde(default = "default_retry_base_delay_secs")]
    retry_base_delay_secs: u64,
    #[serde(default = "default_retry_max_delay_secs")]
    retry_max_delay_secs: u64,
    #[serde(default = "default_cadence_timeout_secs")]
    cadence_timeout_secs: u64,
}

#[derive(Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
struct RawSandbox {
    #[serde(default)]
    runner: Option<String>,
    #[serde(default)]
    backend: Option<String>,
}

#[derive(Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
struct RawToolPolicy {
    #[serde(default)]
    shell_deny_substrings: Vec<String>,
    #[serde(default)]
    shell_deny_prefixes: Vec<String>,
    #[serde(default)]
    write_root: Option<String>,
}

impl Config {
    /// Loads and validates the configuration at `path`.
    pub fn load(path: &Path) -> Result<Config> {
        let contents = read_configuration(path)?;
        let raw: RawConfig = toml::from_str(&contents).map_err(|error| Error::Config {
            path: Some(path.to_string_lossy().into_owned()),
            reason: error.to_string(),
        })?;
        Config::validate(raw, path)
    }

    /// Validates the parsed configuration against the working directory and the
    /// model/effort/tool-policy invariants.
    fn validate(raw: RawConfig, path: &Path) -> Result<Config> {
        if raw.schema_version != SCHEMA_VERSION {
            return Err(Error::Config {
                path: Some(path.to_string_lossy().into_owned()),
                reason: format!(
                    "schema_version must be {SCHEMA_VERSION}, not {}",
                    raw.schema_version
                ),
            });
        }

        let working_directory = match &raw.working_directory {
            Some(value) => PathBuf::from(value),
            None => std::env::current_dir()
                .map_err(|source| io_error("resolve current working directory", None, source))?,
        };
        if !working_directory.is_absolute() {
            return Err(Error::Config {
                path: Some(path.to_string_lossy().into_owned()),
                reason: format!(
                    "working_directory `{}` must be an absolute path",
                    working_directory.display()
                ),
            });
        }
        if !working_directory.exists() {
            return Err(Error::Config {
                path: Some(path.to_string_lossy().into_owned()),
                reason: format!(
                    "working_directory `{}` does not exist",
                    working_directory.display()
                ),
            });
        }

        if raw.models.is_empty() {
            return Err(Error::Config {
                path: Some(path.to_string_lossy().into_owned()),
                reason: "at least one `[[models]]` entry is required".to_owned(),
            });
        }

        let mut models = Vec::with_capacity(raw.models.len());
        let mut seen_ids = std::collections::BTreeSet::new();
        for (index, model) in raw.models.iter().enumerate() {
            if !seen_ids.insert(model.id.clone()) {
                return Err(Error::Config {
                    path: Some(path.to_string_lossy().into_owned()),
                    reason: format!("duplicate model id `{}` at models[{index}]", model.id),
                });
            }
            let base_url = if model.base_url.is_empty() {
                model.provider.default_endpoint().to_owned()
            } else {
                model.base_url.clone()
            };
            if model.model.trim().is_empty() {
                return Err(Error::Config {
                    path: Some(path.to_string_lossy().into_owned()),
                    reason: format!("models[{index}].model must not be empty"),
                });
            }
            if !(MIN_DEADLINE_SECS..=MAX_DEADLINE_SECS).contains(&model.deadline_secs) {
                return Err(Error::Config {
                    path: Some(path.to_string_lossy().into_owned()),
                    reason: format!(
                        "models[{index}].deadline_secs must be between {MIN_DEADLINE_SECS} and {MAX_DEADLINE_SECS}"
                    ),
                });
            }
            if model.retry_base_delay_secs > model.retry_max_delay_secs {
                return Err(Error::Config {
                    path: Some(path.to_string_lossy().into_owned()),
                    reason: format!(
                        "models[{index}].retry_base_delay_secs must not exceed retry_max_delay_secs"
                    ),
                });
            }
            if model.max_attempts < 1 {
                return Err(Error::Config {
                    path: Some(path.to_string_lossy().into_owned()),
                    reason: format!("models[{index}].max_attempts must be at least 1"),
                });
            }
            if !(0..=MAX_DEADLINE_SECS).contains(&model.cadence_timeout_secs) {
                return Err(Error::Config {
                    path: Some(path.to_string_lossy().into_owned()),
                    reason: format!(
                        "models[{index}].cadence_timeout_secs must be between 0 and {MAX_DEADLINE_SECS}"
                    ),
                });
            }
            const MAX_RETRY_DELAY_SECS: u64 = 3600;
            if model.retry_base_delay_secs > MAX_RETRY_DELAY_SECS
                || model.retry_max_delay_secs > MAX_RETRY_DELAY_SECS
            {
                return Err(Error::Config {
                    path: Some(path.to_string_lossy().into_owned()),
                    reason: format!(
                        "models[{index}].retry_*_delay_secs must be between 0 and {MAX_RETRY_DELAY_SECS}"
                    ),
                });
            }
            models.push(Model {
                id: model.id.clone(),
                provider: model.provider,
                base_url,
                model: model.model.clone(),
                deadline_secs: model.deadline_secs,
                max_attempts: model.max_attempts,
                retry_base_delay_secs: model.retry_base_delay_secs,
                retry_max_delay_secs: model.retry_max_delay_secs,
                cadence_timeout_secs: model.cadence_timeout_secs,
            });
        }

        let default_thinking_effort = match &raw.default_thinking_effort {
            Some(value) => agent_runtime::ReasoningEffort::from_str(value).map_err(|_| {
                Error::Config {
                    path: Some(path.to_string_lossy().into_owned()),
                    reason: format!(
                        "default_thinking_effort `{value}` is invalid; expected none, minimal, low, medium, high, xhigh, or max"
                    ),
                }
            })?,
            None => agent_runtime::ReasoningEffort::Medium,
        };

        if !models.iter().any(|model| model.id == raw.default_model) {
            return Err(Error::ModelNotFound {
                requested: raw.default_model.clone(),
                available: models.iter().map(|model| model.id.clone()).collect(),
            });
        }

        let tool_policy = crate::tools::ToolPolicy::from_policy_table(&raw.tool_policy)?;

        Ok(Config {
            schema_version: SCHEMA_VERSION,
            working_directory,
            default_model: raw.default_model,
            default_thinking_effort,
            models,
            tool_policy,
            sandbox: SandboxPaths {
                runner: raw
                    .sandbox
                    .runner
                    .map(PathBuf::from)
                    .unwrap_or_else(SandboxPaths::default_runner),
                backend: raw
                    .sandbox
                    .backend
                    .map(PathBuf::from)
                    .unwrap_or_else(SandboxPaths::default_backend),
            },
        })
    }

    /// Builds an in-memory configuration, used by tests and by the CLI overrides.
    pub fn from_parts(
        working_directory: PathBuf,
        default_model: &str,
        models: Vec<Model>,
        tool_policy: crate::tools::ToolPolicy,
    ) -> Result<Config> {
        if !models.iter().any(|model| model.id == default_model) {
            return Err(Error::ModelNotFound {
                requested: default_model.to_owned(),
                available: models.iter().map(|model| model.id.clone()).collect(),
            });
        }
        Ok(Config {
            schema_version: SCHEMA_VERSION,
            working_directory,
            default_model: default_model.to_owned(),
            default_thinking_effort: agent_runtime::ReasoningEffort::Medium,
            models,
            tool_policy,
            sandbox: SandboxPaths::default(),
        })
    }

    /// The model matching a selector, when present.
    pub fn model(&self, id: &str) -> Option<&Model> {
        self.models.iter().find(|model| model.id == id)
    }
}

fn read_configuration(path: &Path) -> Result<String> {
    let metadata = std::fs::symlink_metadata(path).map_err(|source| {
        io_error(
            "inspect configuration",
            Some(&path.to_string_lossy()),
            source,
        )
    })?;
    if metadata.file_type().is_symlink() || !metadata.file_type().is_file() {
        return Err(Error::Config {
            path: Some(path.to_string_lossy().into_owned()),
            reason: "configuration must be a regular non-link file".to_owned(),
        });
    }
    if metadata.len() > MAX_CONFIG_BYTES {
        return Err(Error::Config {
            path: Some(path.to_string_lossy().into_owned()),
            reason: format!("configuration exceeds the {MAX_CONFIG_BYTES}-byte limit"),
        });
    }
    // `read_to_string` already rejects non-UTF-8 input.
    std::fs::read_to_string(path)
        .map_err(|source| io_error("read configuration", Some(&path.to_string_lossy()), source))
}

//! Markdown rendering for the transcript: parse GitHub-flavored Markdown and
//! emit a flat list of styled, width-limited lines the ratatui transcript
//! draws directly. The conversion is a pure function of its input, so it is
//! unit-tested without a terminal.
//!
//! Supported: headings, emphasis, inline code, fenced and indented code blocks
//! with syntax highlighting, blockquotes, ordered/unordered and task lists,
//! strikethrough, GitHub tables, links, and horizontal rules.

use pulldown_cmark::{Alignment, CodeBlockKind, Event, HeadingLevel, Options, Parser, Tag, TagEnd};
use ratatui::style::{Color, Modifier, Style as RStyle};
use ratatui::text::{Line, Span};
use std::sync::OnceLock;
use syntect::easy::HighlightLines;
use syntect::highlighting::{Color as SColor, FontStyle, Style as SStyle, Theme, ThemeSet};
use syntect::parsing::{SyntaxReference, SyntaxSet};

/// One visual transcript row plus a flag marking whether it is code.
#[derive(Debug, Clone)]
pub struct RenderedLine {
    pub line: Line<'static>,
    pub is_code: bool,
}

/// Styling for each Markdown construct. Defaults suit a dark terminal; the
/// code-block background is derived from the syntect theme.
#[derive(Debug, Clone)]
pub struct MarkdownStyles {
    pub paragraph: RStyle,
    pub heading: [RStyle; 6],
    pub code_inline: RStyle,
    pub code_bg: RStyle,
    pub code_label: RStyle,
    pub code_gutter: RStyle,
    pub quote: RStyle,
    pub quote_gutter: RStyle,
    pub link: RStyle,
    pub link_url: RStyle,
    pub html: RStyle,
    pub rule: RStyle,
    pub list_bullet: RStyle,
    pub task_open: RStyle,
    pub task_closed: RStyle,
    pub table_header: RStyle,
    pub table_sep: RStyle,
}

impl Default for MarkdownStyles {
    fn default() -> Self {
        Self {
            paragraph: RStyle::default(),
            heading: [
                RStyle::default().fg(Color::Red),
                RStyle::default().fg(Color::Yellow),
                RStyle::default().fg(Color::Green),
                RStyle::default().fg(Color::Cyan),
                RStyle::default().fg(Color::Blue),
                RStyle::default().fg(Color::Magenta),
            ],
            code_inline: RStyle::default().bg(Color::DarkGray),
            code_bg: RStyle::default().bg(Color::DarkGray),
            code_label: RStyle::default()
                .fg(Color::DarkGray)
                .add_modifier(Modifier::DIM),
            code_gutter: RStyle::default().fg(Color::Gray),
            quote: RStyle::default().fg(Color::Gray),
            quote_gutter: RStyle::default().fg(Color::DarkGray),
            link: RStyle::default()
                .fg(Color::Cyan)
                .add_modifier(Modifier::BOLD),
            link_url: RStyle::default().fg(Color::DarkGray),
            html: RStyle::default().fg(Color::Gray),
            rule: RStyle::default().fg(Color::DarkGray),
            list_bullet: RStyle::default().fg(Color::DarkGray),
            task_open: RStyle::default().fg(Color::Gray),
            task_closed: RStyle::default().fg(Color::Green),
            table_header: RStyle::default()
                .fg(Color::Cyan)
                .add_modifier(Modifier::BOLD),
            table_sep: RStyle::default().fg(Color::DarkGray),
        }
    }
}

const GUTTER: &str = "\u{258f}";
const BULLET: &str = "\u{2022}";
const CHECKED: &str = "\u{2611}";
const UNCHECKED: &str = "\u{2610}";

fn srgb(c: SColor) -> Color {
    Color::Rgb(c.r, c.g, c.b)
}

fn syntax_set() -> &'static SyntaxSet {
    static LOAD: OnceLock<SyntaxSet> = OnceLock::new();
    LOAD.get_or_init(SyntaxSet::load_defaults_newlines)
}

fn default_theme() -> &'static Theme {
    static LOAD: OnceLock<Theme> = OnceLock::new();
    LOAD.get_or_init(|| {
        let ts = ThemeSet::load_defaults();
        const CANDIDATES: [&str; 8] = [
            "base16_default_dark", "solarized-dark", "gruvbox-dark", "base16-ocean.dark",
            "monokai", "two-point-four-dark", "everforest", "tokyonight",
        ];
        if let Some(theme) = CANDIDATES.iter().find_map(|name| ts.themes.get(*name)) {
            return theme.clone();
        }
        ts.themes
            .values()
            .find(|t| matches!(t.settings.background, Some(c) if c.r < 0x80 && c.g < 0x80 && c.b < 0x80))
            .cloned()
            .or_else(|| ts.themes.values().next().cloned())
            .expect("syntect's default theme set is not empty")
    })
}

/// Renders Markdown to styled, width-limited lines using the default styles.
pub fn render_document(md: &str, width: usize) -> Vec<RenderedLine> {
    render_document_styles(md, width, &MarkdownStyles::default())
}

/// Renders Markdown using supplied styles, for restyling or tests.
pub fn render_document_styles(
    md: &str,
    width: usize,
    styles: &MarkdownStyles,
) -> Vec<RenderedLine> {
    let width = width.max(1);
    let renderer = Render::new(styles, width, syntax_set(), default_theme());
    let options =
        Options::ENABLE_TABLES | Options::ENABLE_STRIKETHROUGH | Options::ENABLE_TASKLISTS;
    let mut renderer = renderer;
    for event in Parser::new_ext(md, options) {
        renderer.handle_event(event);
    }
    renderer.flush_current();
    renderer.out
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum Current {
    None,
    Para,
    Heading(u16),
    Item,
}

enum Layer {
    Emphasis,
    Strong,
    Strike,
    Link(RStyle),
}

enum Run {
    Text(String, RStyle),
    HardBreak,
}

struct ListState {
    ordered: bool,
    next: u64,
}

struct CodeCtx<'a> {
    info: String,
    hl: HighlightLines<'a>,
    pending: String,
}

struct TableCtx {
    aligns: Vec<Alignment>,
    header: Vec<String>,
    rows: Vec<Vec<String>>,
    row: Vec<String>,
    cell: String,
    in_head: bool,
}

struct Render<'a> {
    styles: &'a MarkdownStyles,
    width: usize,
    margin: usize,
    ss: &'a SyntaxSet,
    theme: &'a Theme,
    out: Vec<RenderedLine>,
    current: Current,
    runs: Vec<Run>,
    layers: Vec<Layer>,
    quote_depth: usize,
    quote_buf: Vec<Vec<RenderedLine>>,
    lists: Vec<ListState>,
    item_task: Option<bool>,
    code: Option<CodeCtx<'a>>,
    table: Option<TableCtx>,
}

impl<'a> Render<'a> {
    fn new(styles: &'a MarkdownStyles, width: usize, ss: &'a SyntaxSet, theme: &'a Theme) -> Self {
        Self {
            styles,
            width,
            margin: 0,
            ss,
            theme,
            out: Vec::new(),
            current: Current::None,
            runs: Vec::new(),
            layers: Vec::new(),
            quote_depth: 0,
            quote_buf: Vec::new(),
            lists: Vec::new(),
            item_task: None,
            code: None,
            table: None,
        }
    }

    fn content_width(&self) -> usize {
        self.width.saturating_sub(self.margin).max(1)
    }

    fn emit(&mut self, rendered: RenderedLine) {
        if let Some(buf) = self.quote_buf.last_mut() {
            buf.push(rendered);
        } else {
            self.out.push(rendered);
        }
    }

    fn handle_event(&mut self, event: Event) {
        match event {
            Event::Start(tag) => self.start_tag(tag),
            Event::End(tag_end) => self.end_tag(tag_end),
            Event::Rule => {
                self.flush_current();
                let line = Line::from(vec![Span::styled(
                    String::from('-').repeat(self.content_width().min(60)),
                    self.styles.rule,
                )]);
                self.emit(RenderedLine {
                    line,
                    is_code: false,
                });
            }
            Event::Text(text) => self.on_text(text.as_ref()),
            Event::Code(code) => self.on_code(code.as_ref()),
            Event::SoftBreak => self.on_soft_break(),
            Event::HardBreak => self.runs.push(Run::HardBreak),
            Event::TaskListMarker(checked) => self.item_task = Some(checked),
            Event::Html(html) | Event::InlineHtml(html) => self.on_html(&html),
            _ => {}
        }
    }

    fn on_text(&mut self, text: &str) {
        if let Some(code) = &mut self.code {
            code.pending.push_str(text);
            return;
        }
        if self.table.is_some() {
            if let Some(t) = &mut self.table {
                t.cell.push_str(text);
            }
            return;
        }
        let style = self.current_style();
        match self.runs.last_mut() {
            Some(Run::Text(s, st)) if *st == style => s.push_str(text),
            _ => self.runs.push(Run::Text(text.to_owned(), style)),
        }
    }

    fn on_code(&mut self, code: &str) {
        if self.table.is_some() {
            if let Some(t) = &mut self.table {
                t.cell.push_str(code);
            }
            return;
        }
        let style = self.styles.code_inline;
        match self.runs.last_mut() {
            Some(Run::Text(s, st)) if *st == style => s.push_str(code),
            _ => self.runs.push(Run::Text(code.to_owned(), style)),
        }
    }

    fn on_soft_break(&mut self) {
        if let Some(code) = &mut self.code {
            code.pending.push('\n');
        } else if let Some(t) = &mut self.table {
            t.cell.push(' ');
        } else {
            self.runs
                .push(Run::Text(" ".to_owned(), self.current_style()));
        }
    }

    fn on_html(&mut self, html: &str) {
        if self.current == Current::Item && html.to_lowercase().contains("checkbox") {
            self.item_task = Some(html.to_lowercase().contains("checked"));
            return;
        }
        if let Some(Run::Text(s, _)) = self.runs.last_mut() {
            s.push_str(html);
        } else {
            self.runs.push(Run::Text(html.to_owned(), self.styles.html));
        }
    }

    fn start_tag(&mut self, tag: Tag) {
        match tag {
            Tag::Paragraph => {
                self.flush_current();
                self.current = Current::Para;
            }
            Tag::Heading { level, .. } => {
                self.flush_current();
                self.current = Current::Heading(level_num(level));
            }
            Tag::BlockQuote(_) => {
                self.flush_current();
                self.quote_depth += 1;
                self.margin += 1;
                self.quote_buf.push(Vec::new());
            }
            Tag::CodeBlock(kind) => self.start_code(kind),
            Tag::List(start) => {
                self.lists.push(match start {
                    Some(first) => ListState {
                        ordered: true,
                        next: first,
                    },
                    None => ListState {
                        ordered: false,
                        next: 1,
                    },
                });
            }
            Tag::Item => {
                self.flush_current();
                self.current = Current::Item;
                self.item_task = None;
            }
            Tag::Table(aligns) => {
                self.table = Some(TableCtx {
                    aligns,
                    header: Vec::new(),
                    rows: Vec::new(),
                    row: Vec::new(),
                    cell: String::new(),
                    in_head: false,
                });
            }
            Tag::TableHead => {
                if let Some(t) = &mut self.table {
                    t.in_head = true;
                }
            }
            Tag::TableRow => {
                if let Some(t) = &mut self.table {
                    t.row.clear();
                }
            }
            Tag::TableCell => {
                if let Some(t) = &mut self.table {
                    t.cell.clear();
                }
            }
            Tag::Emphasis => self.layers.push(Layer::Emphasis),
            Tag::Strong => self.layers.push(Layer::Strong),
            Tag::Strikethrough => self.layers.push(Layer::Strike),
            Tag::Link { .. } => self.layers.push(Layer::Link(self.styles.link)),
            _ => {}
        }
    }

    fn start_code(&mut self, kind: CodeBlockKind) {
        let info = match kind {
            CodeBlockKind::Fenced(s) => s.to_string(),
            CodeBlockKind::Indented => String::new(),
        };
        let syntax = find_syntax(self.ss, &info);
        let fallback = self.ss.syntaxes().first().expect("syntax set is not empty");
        let hl = HighlightLines::new(syntax.unwrap_or(fallback), self.theme);
        self.code = Some(CodeCtx {
            info,
            hl,
            pending: String::new(),
        });
    }

    fn end_tag(&mut self, tag_end: TagEnd) {
        match tag_end {
            TagEnd::Paragraph => self.flush_current(),
            TagEnd::Heading(_) => self.flush_current(),
            TagEnd::BlockQuote(_) => self.finish_blockquote(),
            TagEnd::CodeBlock => self.finish_code(),
            TagEnd::List(_) => {
                self.lists.pop();
            }
            TagEnd::Item => self.flush_current(),
            TagEnd::Table => self.finish_table(),
            TagEnd::TableRow => {
                if let Some(t) = &mut self.table {
                    if t.in_head {
                        t.header = std::mem::take(&mut t.row);
                    } else {
                        t.rows.push(std::mem::take(&mut t.row));
                    }
                }
            }
            TagEnd::TableCell => {
                if let Some(t) = &mut self.table {
                    t.row.push(std::mem::take(&mut t.cell));
                }
            }
            TagEnd::TableHead => {
                if let Some(t) = &mut self.table {
                    if t.in_head && !t.row.is_empty() {
                        t.header = std::mem::take(&mut t.row);
                    }
                    t.in_head = false;
                }
            }
            TagEnd::Emphasis | TagEnd::Strong | TagEnd::Strikethrough => {
                self.layers.pop();
            }
            TagEnd::Link => {
                self.layers.pop();
            }
            _ => {}
        }
    }

    fn current_style(&self) -> RStyle {
        let mut bold = false;
        let mut italic = false;
        let mut strike = false;
        for layer in &self.layers {
            match layer {
                Layer::Emphasis => italic = true,
                Layer::Strong => bold = true,
                Layer::Strike => strike = true,
                Layer::Link(_) => {}
            }
        }
        if let Some(Layer::Link(style)) = self.layers.last() {
            let mut style = *style;
            if strike {
                style = style.add_modifier(Modifier::CROSSED_OUT);
            }
            return style;
        }
        let mut style = self.styles.paragraph;
        if bold {
            style = style.add_modifier(Modifier::BOLD);
        }
        if italic {
            style = style.add_modifier(Modifier::ITALIC);
        }
        if strike {
            style = style.add_modifier(Modifier::CROSSED_OUT);
        }
        style
    }

    fn flush_current(&mut self) {
        match self.current {
            Current::Para => {
                for line in wrap_runs(&self.runs, self.content_width()) {
                    self.emit(RenderedLine {
                        line,
                        is_code: false,
                    });
                }
            }
            Current::Heading(_) => self.flush_heading(),
            Current::Item => self.flush_item(),
            Current::None => {}
        }
        self.current = Current::None;
        self.runs.clear();
    }

    fn flush_heading(&mut self) {
        let level = match self.current {
            Current::Heading(level) => level,
            _ => return,
        };
        let style = self.styles.heading[(level as usize).saturating_sub(1).min(5)]
            .add_modifier(Modifier::BOLD);
        let forced: Vec<Run> = self
            .runs
            .iter()
            .map(|run| match run {
                Run::HardBreak => Run::HardBreak,
                Run::Text(text, _) => Run::Text(text.clone(), style),
            })
            .collect();
        for line in wrap_runs(&forced, self.content_width()) {
            self.emit(RenderedLine {
                line,
                is_code: false,
            });
        }
    }

    fn finish_blockquote(&mut self) {
        let lines = self.quote_buf.pop().unwrap_or_default();
        self.quote_depth = self.quote_depth.saturating_sub(1);
        self.margin = self.margin.saturating_sub(1);
        for mut rendered in lines {
            let mut line = Line::from(vec![]);
            for _ in 0..self.quote_depth {
                line.spans
                    .push(Span::styled(GUTTER, self.styles.quote_gutter));
            }
            line.spans.extend(rendered.line.spans);
            rendered.line = line;
            self.emit(rendered);
        }
    }

    fn finish_code(&mut self) {
        let mut code = self.code.take().expect("code block open on close");
        let bg = self
            .theme
            .settings
            .background
            .map(srgb)
            .unwrap_or(Color::Gray);
        let lang = parse_language(&code.info);
        if let Some(lang) = &lang {
            let label = Line::from(vec![
                Span::styled(" ", self.styles.code_gutter),
                Span::styled(lang.clone(), self.styles.code_label),
            ]);
            self.emit(RenderedLine {
                line: label,
                is_code: true,
            });
        }
        let area = self.content_width().saturating_sub(2).max(1);
        let mut sources: Vec<&str> = code.pending.split('\n').collect();
        if sources.last().is_some_and(|s| s.is_empty()) {
            sources.pop();
        }
        for source in sources {
            let ranges = code
                .hl
                .highlight_line(source, self.ss)
                .unwrap_or_else(|_| vec![(SStyle::default(), source)]);
            let spans = clip_ranges(ranges, area, bg);
            let mut line = Line::from(vec![
                Span::styled(GUTTER, self.styles.code_gutter),
                Span::styled(" ", self.styles.code_gutter),
            ]);
            line.spans.extend(spans);
            self.emit(RenderedLine {
                line,
                is_code: true,
            });
        }
    }

    fn flush_item(&mut self) {
        let list = self.lists.last();
        let (prefix, marker_style) = match list {
            Some(s) if s.ordered => (format!("{}.", s.next), self.styles.list_bullet),
            Some(_) => (BULLET.to_owned(), self.styles.list_bullet),
            None => (String::new(), self.styles.list_bullet),
        };
        let marker = match self.item_task {
            Some(true) => Some((CHECKED.to_owned(), self.styles.task_closed)),
            Some(false) => Some((UNCHECKED.to_owned(), self.styles.task_open)),
            None => None,
        };
        let mut lines = wrap_runs(&self.runs, self.content_width());
        if let Some(first) = lines.first_mut() {
            let mut spans = Vec::new();
            if let Some((marker_text, marker_style)) = &marker {
                spans.push(Span::styled(marker_text.clone(), *marker_style));
            } else {
                spans.push(Span::styled(prefix, marker_style));
            }
            spans.append(&mut first.spans);
            first.spans = spans;
        }
        for line in lines {
            self.emit(RenderedLine {
                line,
                is_code: false,
            });
        }
        if let Some(s) = self.lists.last_mut()
            && s.ordered
        {
            s.next += 1;
        }
    }

    fn finish_table(&mut self) {
        let table = self.table.take().expect("table open on close");
        let aligns = table.aligns;
        let header = table.header;
        let rows = table.rows;
        let ncols = aligns.len().max(
            header
                .len()
                .max(rows.iter().map(Vec::len).max().unwrap_or(0)),
        );
        if ncols == 0 {
            return;
        }
        let mut widths: Vec<usize> = (0..ncols)
            .map(|c| {
                header
                    .get(c)
                    .map(|cells| cells.chars().count())
                    .unwrap_or(0)
                    .max(
                        rows.iter()
                            .filter_map(|r| r.get(c))
                            .map(|c| c.chars().count())
                            .max()
                            .unwrap_or(0),
                    )
                    .max(1)
            })
            .collect();
        let sum_widths: usize = widths.iter().sum();
        let needed = sum_widths + ncols + 1;
        if needed > self.content_width() {
            let overflow = needed - self.content_width();
            for w in widths.iter_mut() {
                *w = w.saturating_sub(*w * overflow / sum_widths.max(1)).max(1);
            }
        }
        if let Some(header_line) =
            render_table_row(&header, &widths, &aligns, self.styles.table_header)
        {
            self.emit(RenderedLine {
                line: header_line,
                is_code: false,
            });
        }
        if let Some(sep_spans) = render_table_separator(&widths, &aligns, self.styles.table_sep) {
            self.emit(RenderedLine {
                line: Line::from(sep_spans),
                is_code: false,
            });
        }
        for row in rows {
            if let Some(line) = render_table_row(&row, &widths, &aligns, self.styles.paragraph) {
                self.emit(RenderedLine {
                    line,
                    is_code: false,
                });
            }
        }
    }
}

fn level_num(level: HeadingLevel) -> u16 {
    (level as u32) as u16
}

fn parse_language(info: &str) -> Option<String> {
    let lang = info.split_whitespace().next()?;
    if lang.is_empty() || lang.starts_with('#') || lang.starts_with('.') {
        return None;
    }
    Some(lang.to_ascii_lowercase())
}

fn find_syntax<'a>(ss: &'a SyntaxSet, info: &str) -> Option<&'a SyntaxReference> {
    let lang = parse_language(info)?;
    const ALIASES: [(&str, &str); 24] = [
        ("rs", "Rust"),
        ("py", "Python"),
        ("py3", "Python"),
        ("js", "JavaScript"),
        ("mjs", "JavaScript"),
        ("cjs", "JavaScript"),
        ("ts", "TypeScript"),
        ("tsx", "TypeScript"),
        ("jsx", "JavaScript"),
        ("sh", "Bash"),
        ("bash", "Bash"),
        ("zsh", "Bash"),
        ("yml", "YAML"),
        ("yaml", "YAML"),
        ("toml", "TOML"),
        ("json", "JSON"),
        ("css", "CSS"),
        ("html", "HTML"),
        ("sql", "SQL"),
        ("go", "Go"),
        ("rb", "Ruby"),
        ("kt", "Kotlin"),
        ("c", "C"),
        ("cpp", "C++"),
    ];
    if let Some((_, name)) = ALIASES.iter().find(|(alias, _)| *alias == lang)
        && let Some(s) = ss.find_syntax_by_name(name)
    {
        return Some(s);
    }
    ss.find_syntax_by_extension(&lang)
        .or_else(|| ss.find_syntax_by_name(&lang))
        .or_else(|| ss.find_syntax_by_name(&lang.to_ascii_uppercase()))
}

struct Word {
    text: String,
    style: RStyle,
    space_before: bool,
}

/// Wraps styled runs to `width`, merging same-style runs and breaking only at
/// whitespace; an over-long token is chunked rather than dropped.
fn wrap_runs(runs: &[Run], width: usize) -> Vec<Line<'static>> {
    let width = width.max(10);
    let chunks: Vec<&[Run]> = {
        let mut chunks = Vec::new();
        let mut start = 0;
        for (i, run) in runs.iter().enumerate() {
            if matches!(run, Run::HardBreak) {
                chunks.push(&runs[start..i]);
                start = i + 1;
            }
        }
        if start < runs.len() {
            chunks.push(&runs[start..]);
        }
        chunks
    };
    let mut lines = Vec::new();
    for chunk in chunks {
        let mut merged: Vec<(String, RStyle)> = Vec::new();
        for run in chunk {
            if let Run::Text(text, style) = run {
                if let Some((last, last_style)) = merged.last_mut()
                    && last_style == style
                {
                    last.push_str(text);
                    continue;
                }
                merged.push((text.clone(), *style));
            }
        }
        let mut words: Vec<Word> = Vec::new();
        for (text, style) in merged {
            for token in text.split_whitespace() {
                words.push(Word {
                    text: token.to_owned(),
                    style,
                    space_before: !words.is_empty(),
                });
            }
        }
        greedy_wrap(words, width, &mut lines);
    }
    lines
}

fn greedy_wrap(words: Vec<Word>, width: usize, lines: &mut Vec<Line<'static>>) {
    lines.push(Line::from(vec![]));
    for word in words {
        let word_len = word.text.chars().count();
        if word_len > width {
            if !lines.last().expect("a line exists").spans.is_empty() {
                lines.push(Line::from(vec![]));
            }
            for chunk in word
                .text
                .chars()
                .collect::<Vec<char>>()
                .chunks(width)
                .map(|c| c.iter().collect::<String>())
            {
                lines.push(Line::from(vec![Span::styled(chunk, word.style)]));
            }
            continue;
        }
        let last = lines.last_mut().expect("a line exists");
        let extra = if !last.spans.is_empty() && word.space_before {
            1
        } else {
            0
        };
        if !last.spans.is_empty() && last.width() + extra + word_len > width {
            lines.push(Line::from(vec![]));
        }
        let last = lines.last_mut().expect("a line exists");
        if !last.spans.is_empty() && word.space_before {
            last.spans.push(Span::styled(" ", RStyle::default()));
        }
        last.spans.push(Span::styled(word.text.clone(), word.style));
    }
}

fn clip_ranges(ranges: Vec<(SStyle, &str)>, max_chars: usize, bg: Color) -> Vec<Span<'static>> {
    let mut spans = Vec::new();
    let mut used = 0usize;
    for (style, text) in ranges {
        let chars: Vec<char> = text.chars().collect();
        if used + chars.len() <= max_chars {
            spans.push(Span::styled(text.to_owned(), syntect_style(style, bg)));
            used += chars.len();
        } else {
            let remaining = max_chars.saturating_sub(used);
            if remaining > 0 {
                let s: String = chars[..remaining].iter().collect();
                spans.push(Span::styled(s, syntect_style(style, bg)));
            }
            break;
        }
    }
    spans
}

fn syntect_style(style: SStyle, bg: Color) -> RStyle {
    let mut out = RStyle::default().fg(srgb(style.foreground)).bg(bg);
    let fs = style.font_style;
    if fs.contains(FontStyle::BOLD) {
        out = out.add_modifier(Modifier::BOLD);
    }
    if fs.contains(FontStyle::ITALIC) {
        out = out.add_modifier(Modifier::ITALIC);
    }
    if fs.contains(FontStyle::UNDERLINE) {
        out = out.add_modifier(Modifier::UNDERLINED);
    }
    out
}

fn render_table_row(
    cells: &[String],
    widths: &[usize],
    aligns: &[Alignment],
    style: RStyle,
) -> Option<Line<'static>> {
    if cells.is_empty() {
        return None;
    }
    let mut spans = vec![Span::styled(" ", style)];
    for (i, width) in widths.iter().enumerate() {
        if i > 0 {
            spans.push(Span::styled(" ", style));
        }
        let cell = cells.get(i).map(String::as_str).unwrap_or("");
        let aligned = align_cell(
            cell,
            *width,
            aligns.get(i).copied().unwrap_or(Alignment::Left),
        );
        spans.push(Span::styled(aligned, style));
    }
    spans.push(Span::styled(" ", style));
    Some(Line::from(spans))
}

fn render_table_separator(
    widths: &[usize],
    aligns: &[Alignment],
    style: RStyle,
) -> Option<Vec<Span<'static>>> {
    if widths.is_empty() {
        return None;
    }
    let mut spans = vec![Span::styled(" ", style)];
    for (i, width) in widths.iter().enumerate() {
        if i > 0 {
            spans.push(Span::styled(" ", style));
        }
        let align = aligns.get(i).copied().unwrap_or(Alignment::Left);
        spans.push(Span::styled(separator_cell(*width, align), style));
    }
    spans.push(Span::styled(" ", style));
    Some(spans)
}

/// A table separator cell of exactly `width` columns, marked with a colon to
/// show column alignment: none for left (`---`), one at each end for center
/// (`:--:`), and one at the right for right (`---:`). Keeping the width equal to
/// the column width keeps the separator row straight with the cells.
fn separator_cell(width: usize, align: Alignment) -> String {
    let width = width.max(1);
    let mut cell: Vec<char> = std::iter::repeat_n('-', width).collect();
    match align {
        Alignment::None | Alignment::Left => {}
        Alignment::Center => {
            cell[0] = ':';
            cell[width - 1] = ':';
        }
        Alignment::Right => cell[width - 1] = ':',
    }
    cell.into_iter().collect()
}

fn align_cell(cell: &str, width: usize, align: Alignment) -> String {
    let shown: Vec<char> = cell.chars().take(width).collect();
    let len = shown.len();
    if len >= width {
        return shown.iter().collect();
    }
    let padding = width - len;
    let (left, right) = match align {
        Alignment::Right => (0, padding),
        Alignment::Center => (padding / 2, padding - padding / 2),
        _ => (padding, 0),
    };
    let mut out = String::new();
    out.push_str(&" ".repeat(left));
    out.extend(shown);
    out.push_str(&" ".repeat(right));
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn joined(lines: &[RenderedLine]) -> String {
        lines.iter().map(|rl| rl.line.to_string()).collect()
    }

    #[test]
    fn headings_are_bold() {
        let out = render_document("# Title\n\nsome text\n", 40);
        assert_eq!(out[0].line.to_string(), "Title");
        assert!(
            out[0].line.spans[0]
                .style
                .add_modifier
                .contains(Modifier::BOLD)
        );
        assert_eq!(out[1].line.to_string(), "some text");
    }

    #[test]
    fn bold_applies_modifier() {
        let out = render_document("a **b** c", 40);
        assert_eq!(out[0].line.to_string(), "a b c");
        let strong = out[0]
            .line
            .spans
            .iter()
            .find(|s| s.content == "b")
            .expect("b span");
        assert!(strong.style.add_modifier.contains(Modifier::BOLD));
    }

    #[test]
    fn inline_code_is_styled() {
        let out = render_document("use `cargo build` now", 40);
        assert_eq!(out[0].line.to_string(), "use cargo build now");
        assert!(
            out[0]
                .line
                .spans
                .iter()
                .any(|s| s.style.bg == Some(Color::DarkGray))
        );
    }

    #[test]
    fn code_fence_is_highlighted_and_marked() {
        let out = render_document("```rust\nfn main() {}\n```\n", 40);
        assert!(out.iter().all(|rl| rl.is_code));
        assert_eq!(out[0].line.to_string(), " rust");
        assert!(out[1].line.to_string().contains("fn main() {}"));
    }

    #[test]
    fn indented_code_has_no_language_label() {
        let out = render_document("a code block\n\n    let x = 1;\n", 40);
        assert_eq!(out[0].line.to_string(), "a code block");
        let code_lines: Vec<&RenderedLine> = out.iter().filter(|rl| rl.is_code).collect();
        assert_eq!(code_lines.len(), 1);
        assert!(code_lines[0].line.to_string().contains("let x = 1;"));
        assert!(!out.iter().any(
            |rl| rl.line.to_string().contains("rust") || rl.line.to_string().contains("python")
        ));
    }

    #[test]
    fn table_renders_header_separator_and_row() {
        let out = render_document("| a | b |\n| --- | --- |\n| 1 | 2 |\n", 40);
        assert_eq!(out[0].line.to_string(), " a b ");
        assert_eq!(out[1].line.to_string(), " - - ");
        assert_eq!(out[2].line.to_string(), " 1 2 ");
    }

    #[test]
    fn table_separator_marks_alignment() {
        let out = render_document(
            "| aaa | bbb | ccc |\n| --- | :--: | ---: |\n| 1 | 2 | 3 |\n",
            40,
        );
        let sep = out[1].line.to_string();
        assert!(sep.contains(":-:"), "center marker: {sep:?}");
        assert!(sep.contains("-:"), "right marker: {sep:?}");
    }

    #[test]
    fn task_list_uses_checkboxes() {
        let text = joined(&render_document("- [x] done\n- [ ] todo\n", 40));
        assert!(text.contains(CHECKED), "checked box: {text:?}");
        assert!(text.contains(UNCHECKED), "unchecked box: {text:?}");
    }

    #[test]
    fn ordered_list_numbers_progress() {
        let out = render_document("1. one\n2. two\n", 40);
        assert!(out[0].line.to_string().starts_with("1."));
        assert!(out[1].line.to_string().starts_with("2."));
    }

    #[test]
    fn long_word_is_chunked_not_overflowing() {
        let word = String::from("a").repeat(50);
        for line in render_document(&word, 20) {
            assert!(line.line.width() <= 20, "line too wide: {}", line.line);
        }
    }
}

