/// User-selected overrides applied over a loaded configuration.
pub struct Overrides {
    /// The model id to select for this session.
    pub model: Option<String>,
    /// The thinking effort to select for this session.
    pub effort: Option<ReasoningEffort>,
    /// The working directory to select for this session.
    pub cwd: Option<PathBuf>,
    /// The language tool profile to select for this session.
    pub profile: Option<crate::tools::ToolProfile>,
    /// Directory for the session journal + transcript. `None` means the
    /// default (`.agent-runner/runs` under the working directory).
    pub log_dir: Option<PathBuf>,
    /// Model context window in tokens. `None` uses the default (8192).
    pub context_limit: Option<usize>,
    /// Disable durable session logging entirely.
    pub no_logs: bool,
    /// The resolved configuration path, shown in the help overlay.
    pub config_path: Option<PathBuf>,
}

/// Runs the interactive UI to completion and returns the process exit code.
pub fn run(config: Config, overrides: Overrides) -> ExitCode {
    if !std::io::stdin().is_terminal() {
        eprintln!(
            "{}",
            Error::NotInteractive {
                reason: "standard input is not a terminal".to_owned()
            }
            .describe()
        );
        return ExitCode::from(2);
    }

    let model_id = overrides.model.as_deref().unwrap_or(&config.default_model);
    let model = match config.model(model_id) {
        Some(model) => model.clone(),
        None => {
            let available = config
                .models
                .iter()
                .map(|model| model.id.clone())
                .collect::<Vec<_>>();
            eprintln!(
                "{}",
                Error::ModelNotFound {
                    requested: model_id.to_owned(),
                    available,
                }
                .describe()
            );
            return ExitCode::from(2);
        }
    };

    let app_model_label = app_model_id(&config, &model);

    let effort = overrides.effort.unwrap_or(config.default_thinking_effort);
    let working_directory = overrides
        .cwd
        .clone()
        .unwrap_or_else(|| config.working_directory.clone());

    let mut registry = match ToolRegistry::discover(config.tool_policy.clone()) {
        Ok(registry) => registry,
        Err(error) => {
            eprintln!("{}", error.describe());
            return ExitCode::from(error.exit_code());
        }
    };
    if let Some(profile) = overrides.profile {
        registry = registry.with_profiles(vec![profile]);
    }
    let tool_defs = registry.tool_definitions();

    let executor = Arc::new(SandboxExecutor::new(
        registry,
        config.sandbox.clone(),
        working_directory.clone(),
    ));

    let builder = SessionBuilder {
        config: config.clone(),
        executor,
        tool_defs,
        context_limit: overrides
            .context_limit
            .unwrap_or(crate::context::DEFAULT_CONTEXT_TOKENS),
        log_dir: overrides.log_dir.clone(),
        no_logs: overrides.no_logs,
        working_directory,
    };

    let initial = match builder.start(&model, effort) {
        Ok(worker) => worker,
        Err(error) => {
            eprintln!("{}", error.describe());
            return ExitCode::from(error.exit_code());
        }
    };

    let (width, height) = size().unwrap_or((100, 30));
    let model_ids: Vec<String> = config.models.iter().map(|model| model.id.clone()).collect();
    let app = App::new(
        &model_ids,
        &app_model_label,
        effort,
        overrides.config_path,
        width,
        height,
    );

    match ui_loop(app, &builder, Some(initial)) {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("{}", error.describe());
            ExitCode::from(error.exit_code())
        }
    }
}

/// Builds session workers for the selected model and effort. Each worker owns
/// its transport, conversation, context window, and durable log; switching the
/// model or the effort starts a fresh worker (the model's conversation context
/// restarts, which the UI announces).
struct SessionBuilder {
    config: Config,
    executor: Arc<SandboxExecutor>,
    tool_defs: Vec<agent_runtime::ToolDefinition>,
    context_limit: usize,
    log_dir: Option<PathBuf>,
    no_logs: bool,
    working_directory: PathBuf,
}

/// One live session worker: the model loop thread plus its channels.
struct Worker {
    handle: run::SessionHandle,
    rx: mpsc::Receiver<crate::session::Event>,
    prompt_tx: mpsc::Sender<String>,
    model_id: String,
    effort: ReasoningEffort,
}

impl SessionBuilder {
    /// Starts a session worker for `model` with `effort`.
    fn start(&self, model: &Model, effort: ReasoningEffort) -> Result<Worker> {
        let transport = build_transport(model)?;
        // Derive the retry policy from the model's own settings so a turn that
        // is generation-bound recovers from transient failures with back-off.
        let retry = RetryPolicy::new(
            model.max_attempts,
            Duration::from_secs(model.retry_base_delay_secs),
            Duration::from_secs(model.retry_max_delay_secs),
        );
        let session = AgentSession::new(
            model.clone(),
            effort,
            self.tool_defs.clone(),
            run::system_prompt(&self.config.tool_policy.write_root),
        );
        let context = ContextManager::new(self.context_limit, 6);
        let recorder = if self.no_logs {
            None
        } else {
            let dir = self.log_dir.clone().unwrap_or_else(|| {
                self.working_directory
                    .join(crate::session_log::DEFAULT_LOG_DIR)
            });
            match SessionLog::open(&dir, format!("agent-runner-{}", model.id)) {
                Ok(log) => Some(Box::new(log) as Box<dyn Recorder>),
                Err(error) => {
                    // Logging is best-effort: report, then continue without it.
                    eprintln!(
                        "{}",
                        Error::Io {
                            operation: "open session log directory".to_owned(),
                            path: Some(dir.to_string_lossy().into_owned()),
                            source: error,
                        }
                        .describe()
                    );
                    None
                }
            }
        };
        let (handle, rx, prompt_tx) = start(
            session,
            transport,
            Arc::clone(&self.executor),
            context,
            recorder,
            retry,
        );
        Ok(Worker {
            handle,
            rx,
            prompt_tx,
            model_id: model.id.clone(),
            effort,
        })
    }
}

fn app_model_id(config: &Config, model: &Model) -> String {
    config
        .models
        .iter()
        .find(|candidate| candidate.id == model.id)
        .map(|candidate| candidate.id.clone())
        .unwrap_or_else(|| model.id.clone())
}

fn build_transport(model: &Model) -> Result<agent_runtime::DirectModelTransport> {
    let provider = model.provider.to_agent_provider();
    let deadline = Duration::from_secs(model.deadline_secs.max(1));
    let mut transport = agent_runtime::DirectModelTransport::new(
        provider,
        &model.base_url,
        deadline,
        8 * 1024 * 1024,
    )
    .map_err(|error| Error::ModelTransport {
        model: Some(model.id.clone()),
        reason: error.to_string(),
    })?;
    // A generous per-turn deadline is safe to relax because the inter-token
    // cadence watchdog bounds a stalled provider: if no token arrives within
    // `cadence_timeout_secs` after the first token, the turn is retried instead
    // of hanging until the (long) deadline. `0` disables the watchdog.
    if model.cadence_timeout_secs > 0 {
        transport = transport.with_cadence_timeout(Duration::from_secs(model.cadence_timeout_secs));
    }
    Ok(transport)
}

fn ui_loop(mut app: App, builder: &SessionBuilder, mut worker: Option<Worker>) -> Result<()> {
    enable_raw_mode()?;
    let mut stdout = std::io::stdout();
    execute!(stdout, EnterAlternateScreen, EnableMouseCapture)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let result = run_ui(&mut terminal, &mut app, builder, &mut worker);

    disable_raw_mode()?;
    execute!(
        terminal.backend_mut(),
        LeaveAlternateScreen,
        DisableMouseCapture
    )?;
    terminal.show_cursor()?;
    result
}

fn run_ui<M: std::io::Write>(
    terminal: &mut Terminal<CrosstermBackend<M>>,
    app: &mut App,
    builder: &SessionBuilder,
    worker: &mut Option<Worker>,
) -> Result<()> {
    loop {
        terminal.draw(|frame| render::render(frame, app))?;

        // Drain loop events without blocking.
        if let Some(current) = worker.as_ref() {
            app.pump(&current.rx)?;
        }

        if event::poll(Duration::from_millis(150))? {
            match event::read()? {
                CrosstermEvent::Resize(width, height) => app.resize(width, height),
                CrosstermEvent::Key(key) if key.kind == KeyEventKind::Press => {
                    match app.on_key(key) {
                        KeyAction::Submit => {
                            let text = app.take_pending_prompt();
                            let changed = match worker.as_ref() {
                                Some(current) => {
                                    current.model_id != app.model || current.effort != app.effort
                                }
                                None => true,
                            };
                            if text.is_some() && changed {
                                // A model or effort change applies to the next
                                // prompt: the old worker is cancelled and
                                // joined (dropped), then a fresh session starts.
                                let model = builder.config.model(&app.model).ok_or_else(|| {
                                    Error::ModelNotFound {
                                        requested: app.model.clone(),
                                        available: builder
                                            .config
                                            .models
                                            .iter()
                                            .map(|model| model.id.clone())
                                            .collect(),
                                    }
                                })?;
                                *worker = Some(builder.start(model, app.effort)?);
                            }
                            if let (Some(text), Some(current)) = (text, worker.as_ref()) {
                                let _ = current.prompt_tx.send(text);
                            }
                        }
                        KeyAction::Cancel => {
                            if let Some(current) = worker.as_ref() {
                                current.handle.cancel();
                            }
                        }
                        KeyAction::Quit => {
                            app.should_quit = true;
                        }
                        KeyAction::Idle => {}
                    }
                }
                CrosstermEvent::Key(_) => {}
                CrosstermEvent::Mouse(mouse) if mouse.kind == MouseEventKind::ScrollUp => {
                    app.scroll_up(3);
                }
                CrosstermEvent::Mouse(mouse) if mouse.kind == MouseEventKind::ScrollDown => {
                    app.scroll_down(3);
                }
                _ => {}
            }
        }

        if app.should_quit {
            break;
        }
    }
    Ok(())
}

//! Durable session log for the agent loop.
//!
//! Every turn is recorded in two complementary forms, so the full transcript —
//! including the agent's reasoning / thinking — survives even when compaction
//! removes older turns from the model context and the UI collapses thinking:
//!
//! * a structured `.jsonl` journal built on `agent_runtime::TrajectoryRecorder`,
//!   which is what an automated replay or the compliance review consumes; and
//! * a human-readable transcript log, which is what a curious person reads to
//!   follow how a conclusion was reached.
//!
//! The journal uses the same closed event vocabulary as the broader Kvist
//! runtime, so the two remain interchangeable. Nothing here leaks secrets: tool
//! results are bounded exactly as they are folded back to the model, and only
//! tool *names* and their argument shapes reach the structured record.

use std::fs::{File, OpenOptions};
use std::io::Write;
use std::path::{Path, PathBuf};
use std::time::{Instant, SystemTime, UNIX_EPOCH};

use crate::session::Recorder;
use agent_runtime::{ModelTurn, ModelUsage, TrajectoryEvent, TrajectoryRecorder};

/// Default location for the structured journal and readable transcript.
pub const DEFAULT_LOG_DIR: &str = ".agent-runner/runs";
/// Maximum bytes of a single tool result written to the log (matches the
/// value folded back to the model).
const MAX_LOG_OUTPUT_BYTES: usize = 64 * 1024;

/// Collapses a reasoning string to a single readable line for the transcript.
fn reason_lines(reasoning: &str) -> String {
    let one: String = reasoning.lines().collect::<Vec<_>>().join(" ");
    bounded_string(&one, 500)
}

/// Truncates `text` to at most `max` bytes, lossily and with an ellipsis.
fn bounded_string(text: &str, max: usize) -> String {
    let bytes = text.as_bytes();
    if bytes.len() <= max {
        text.to_owned()
    } else {
        let kept = String::from_utf8_lossy(&bytes[..max]).into_owned();
        format!("...{kept}")
    }
}

/// Bounds the tool stdout shown in the structured record.
fn bounded_stdout(stdout: &str) -> String {
    bounded_string(stdout, MAX_LOG_OUTPUT_BYTES)
}

/// Bounds the tool stderr shown in the structured record.
fn bounded_stderr(stderr: &str) -> String {
    bounded_string(stderr, MAX_LOG_OUTPUT_BYTES)
}

/// The durable session log: structured journal plus readable transcript, with
/// token and timing stats for the live working-speed display.
#[derive(Debug)]
pub struct SessionLog {
    recorder: TrajectoryRecorder,
    transcript: Option<File>,
    transcript_path: PathBuf,
    started_at: Instant,
    task_id: String,
    turn: usize,
    total_input_tokens: u64,
    total_output_tokens: u64,
}

impl SessionLog {
    /// Opens a new journal and transcript under `log_dir`, timestamped by the
    /// current time. Creates the log directory if needed.
    pub fn open(log_dir: &Path, task_id: impl Into<String>) -> std::io::Result<SessionLog> {
        std::fs::create_dir_all(log_dir)?;
        let stamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_micros())
            .unwrap_or(0);
        let journal = log_dir.join(format!("session-{stamp}.jsonl"));
        let transcript_path = log_dir.join(format!("session-{stamp}.log"));
        // Eagerly create the journal so it exists as soon as the log opens,
        // matching the transcript below. `record_event` only opens it with
        // `append`, so it would not otherwise exist until the first write.
        std::fs::File::create(&journal)?;
        let recorder = TrajectoryRecorder::new(journal.clone());
        let file = OpenOptions::new()
            .create(true)
            .append(true)
            .open(&transcript_path)?;
        Ok(SessionLog {
            recorder,
            transcript: Some(file),
            transcript_path,
            started_at: Instant::now(),
            task_id: task_id.into(),
            turn: 0,
            total_input_tokens: 0,
            total_output_tokens: 0,
        })
    }

    /// The journal path, for reporting back to the user.
    pub fn journal_path(&self) -> &Path {
        self.recorder.path()
    }

    /// The transcript path, for reporting back to the user.
    pub fn transcript_path(&self) -> &Path {
        &self.transcript_path
    }

    /// The running task identifier.
    pub fn task_id(&self) -> &str {
        &self.task_id
    }

    /// Cumulative input tokens observed across the session.
    pub fn total_input_tokens(&self) -> u64 {
        self.total_input_tokens
    }

    /// Cumulative output tokens observed across the session.
    pub fn total_output_tokens(&self) -> u64 {
        self.total_output_tokens
    }

    /// Total tokens observed across the session.
    pub fn total_tokens(&self) -> u64 {
        self.total_input_tokens + self.total_output_tokens
    }

    /// Wall-clock seconds since the session started.
    pub fn elapsed_secs(&self) -> f64 {
        self.started_at.elapsed().as_secs_f64()
    }

    fn transcript(&mut self, line: &str) {
        if let Some(file) = self.transcript.as_mut() {
            let _ = writeln!(file, "{line}");
        }
    }

    fn record(&self, event: TrajectoryEvent) {
        let _ = self.recorder.record_event(&event);
    }

    fn timestamp_ms() -> u64 {
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_millis() as u64)
            .unwrap_or(0)
    }

    /// Writes the structured session-start event.
    pub fn session_start(&mut self) {
        self.record(TrajectoryEvent::SessionStart {
            session_id: self.task_id.clone(),
            task_id: self.task_id.clone(),
            timestamp: Self::timestamp_ms(),
        });
        self.transcript(&format!(
            "== session {} started {}s ago ==",
            self.task_id,
            self.elapsed_secs().round()
        ));
    }

    /// Begins recording one turn and captures the full reasoning trace for this
    /// turn, which compaction and the UI may drop but the log keeps.
    pub fn turn_start(&mut self, turn: &ModelTurn) -> usize {
        self.turn += 1;
        let turn_idx = self.turn;
        self.record(TrajectoryEvent::TurnStart {
            turn: turn_idx,
            timestamp: Self::timestamp_ms(),
        });
        if let Some(reasoning) = &turn.reasoning
            && !reasoning.trim().is_empty()
        {
            self.record(TrajectoryEvent::ModelReasoning {
                turn: turn_idx,
                reasoning: reasoning.clone(),
            });
            self.transcript(&format!(
                "[turn {turn_idx}] reasoning: {}",
                reason_lines(reasoning)
            ));
        }
        turn_idx
    }

    /// Records a completed turn, folding in provider token usage.
    pub fn turn_finish(
        &mut self,
        turn: usize,
        usage: &Option<agent_runtime::ModelUsage>,
        finish_reason: &str,
    ) {
        if let Some(usage) = usage {
            self.total_input_tokens += usage.input_tokens;
            self.total_output_tokens += usage.output_tokens;
        }
        let output = usage.map(|u| u.output_tokens).unwrap_or(0);
        let input = usage.map(|u| u.input_tokens).unwrap_or(0);
        self.record(TrajectoryEvent::TurnFinish {
            turn,
            output_tokens: Some(output),
            finish_reason: finish_reason.to_owned(),
        });
        self.record(TrajectoryEvent::PromptEval {
            turn,
            cached_tokens: None,
            new_tokens: Some(input),
            eval_duration_ms: None,
        });
    }

    /// Records an approved tool dispatch and its sandbox observation.
    pub fn tool_result(
        &mut self,
        turn: usize,
        call_id: &str,
        tool: &str,
        args: &serde_json::Value,
        outcome: &crate::sandbox::ToolOutcome,
    ) {
        let stdout = outcome.output_text(MAX_LOG_OUTPUT_BYTES);
        let stderr = outcome.error_text(MAX_LOG_OUTPUT_BYTES);
        self.record(TrajectoryEvent::ToolDispatch {
            turn,
            call_id: call_id.to_owned(),
            tool: tool.to_owned(),
            args: args.clone(),
            action_hash: format!("{tool}:{call_id}"),
        });
        self.record(TrajectoryEvent::ToolResult {
            turn,
            call_id: call_id.to_owned(),
            tool: tool.to_owned(),
            stdout: bounded_stdout(&stdout),
            stderr: bounded_stderr(&stderr),
            exit_code: outcome.status.unwrap_or(-1),
            bytes: outcome.stdout.len() + outcome.stderr.len(),
            state_mutated: !outcome.stdout.is_empty() || !outcome.stderr.is_empty(),
        });
        let summary = format!("[turn {turn}] {tool} {call_id}: {stdout}{stderr}");
        self.transcript(&summary);
    }

    /// Writes the terminal session-finish event with session totals.
    pub fn session_finish(&mut self, success: bool) {
        self.record(TrajectoryEvent::SessionFinish {
            session_id: self.task_id.clone(),
            task_id: self.task_id.clone(),
            total_turns: self.turn,
            total_tokens: self.total_tokens(),
            success,
        });
        self.transcript(&format!(
            "== session {} finished: {} turns, {} tokens, {}s, {} ==",
            self.task_id,
            self.turn,
            self.total_tokens(),
            self.elapsed_secs().round(),
            if success { "ok" } else { "cancelled/failed" }
        ));
    }
}

impl Recorder for SessionLog {
    fn session_start(&mut self) {
        SessionLog::session_start(self);
    }

    fn turn_start(&mut self, turn: &ModelTurn) -> usize {
        SessionLog::turn_start(self, turn)
    }

    fn turn_finish(&mut self, turn: usize, usage: &Option<ModelUsage>, finish_reason: &str) {
        SessionLog::turn_finish(self, turn, usage, finish_reason);
    }

    fn tool_result(
        &mut self,
        turn: usize,
        call_id: &str,
        tool: &str,
        args: &serde_json::Value,
        outcome: &crate::sandbox::ToolOutcome,
    ) {
        SessionLog::tool_result(self, turn, call_id, tool, args, outcome);
    }

    fn session_finish(&mut self, success: bool) {
        SessionLog::session_finish(self, success);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn journal_and_transcript_are_created_under_log_dir() {
        let dir = tempfile::tempdir().unwrap();
        let log = SessionLog::open(dir.path(), "task-1").expect("open");
        let jp = log.journal_path().to_string_lossy().to_string();
        let tp = log.transcript_path().to_string_lossy().to_string();
        assert!(jp.ends_with(".jsonl"));
        assert!(tp.ends_with(".log"));
        assert!(Path::new(&jp).exists());
        assert!(Path::new(&tp).exists());
    }

    #[test]
    fn session_records_start_and_finish_events() {
        let dir = tempfile::tempdir().unwrap();
        let mut log = SessionLog::open(dir.path(), "task-2").expect("open");
        log.session_start();
        log.session_finish(true);
        let contents = std::fs::read_to_string(log.journal_path()).unwrap();
        assert!(contents.contains("session_start"));
        assert!(contents.contains("session_finish"));
    }

    #[test]
    fn tokens_accumulate_across_turns() {
        let dir = tempfile::tempdir().unwrap();
        let mut log = SessionLog::open(dir.path(), "task-3").expect("open");
        let usage = Some(agent_runtime::ModelUsage {
            input_tokens: 10,
            output_tokens: 5,
            total_tokens: 15,
        });
        log.turn_finish(1, &usage, "stop");
        log.turn_finish(2, &usage, "stop");
        assert_eq!(log.total_input_tokens(), 20);
        assert_eq!(log.total_output_tokens(), 10);
        assert_eq!(log.total_tokens(), 30);
    }

    #[test]
    fn transcript_records_reasoning() {
        let dir = tempfile::tempdir().unwrap();
        let mut log = SessionLog::open(dir.path(), "task-4").expect("open");
        log.session_start();
        let turn = ModelTurn {
            text: "done".to_owned(),
            reasoning: Some("because reasons".to_owned()),
            tool_intents: vec![],
            finish_reason: agent_runtime::FinishReason::Stop,
            provider: agent_runtime::LocalModelProvider::LlamaServer,
            model: "m".to_owned(),
            response_id: None,
            provider_request_id: None,
            usage: Some(agent_runtime::ModelUsage {
                input_tokens: 1,
                output_tokens: 1,
                total_tokens: 2,
            }),
        };
        let idx = log.turn_start(&turn);
        log.turn_finish(idx, &turn.usage, "stop");
        let transcript = std::fs::read_to_string(log.transcript_path()).unwrap();
        assert!(transcript.contains("reasoning"));
        assert!(transcript.contains("because reasons"));
    }
}

